INSERT INTO `ai_playerbot_texts` (`id`, `name`, `text`, `say_type`, `reply_type`, `text_loc1`, `text_loc2`, `text_loc3`, `text_loc4`, `text_loc5`, `text_loc6`, `text_loc7`, `text_loc8`) VALUES
	(1, 'string_unknown_area', 'the middle of nowhere', 0, 0, '아무 데도 아닌 곳', 'au milieu de nulle part', 'am Arsch der Welt', '荒无人烟之地', '荒無人烟之地', 'en mitad de la nada', 'en mitad de la nada', 'посреди нигде'),
	(2, 'string_unknown_area', 'an undisclosed location', 0, 0, '알려지지 않은 장소', 'un lieu non divulgué', 'an einem geheimen Ort', '某个不为人知的地方', '某個不為人知的地方', 'un sitio no revelado', 'un sitio no revelado', 'в неопределенном месте'),
	(3, 'string_unknown_area', 'somewhere', 0, 0, '어딘가', 'Quelque part.', 'irgendwo', '某个地方', '某個地方', 'en algún sitio', 'en algún sitio', 'где-то'),
	(4, 'string_empty_link', 'something', 0, 0, '뭔가', 'quelque chose', 'irgendwas', '某样东西', '某样东西', 'algo', 'algo', 'что-то'),
	(5, 'broadcast_looting_item_normal', 'wonder what %item_link tastes like', 0, 0, '%item_link 맛이 어떨지 궁금하네', 'Je me demande à quoi %item_link peut bien goûter.', 'frag mich, wie %item_link wohl schmeckt', '想知道这%item_link吃起来啥味儿', '想知道這%item_link吃起來啥味儿', 'me pregunto a qué sabrá %item_link', 'me pregunto a qué sabrá %item_link', 'интересно, какой на вкус %item_link'),
	(6, 'broadcast_looting_item_poor', 'nooo, I got %item_link', 0, 0, '아니, %item_link 나왔어', 'Oh non, j’ai reçu %item_link', 'neeein, ich hab %item_link bekommen', '不！我捡了个%item_link', '不！我捡了個%item_link', 'nooo, me salió %item_link', 'nooo, me salió %item_link', 'нет, мне выпал %item_link'),
	(7, 'broadcast_looting_item_poor', 'aww not this trash again %item_link', 0, 0, '아 또 이 쓰레기 %item_link', 'Encore cette poubelle %item_link.', 'ah nee, nicht schon wieder dieser Müll: %item_link', '哎，又是这破烂%item_link', '哎，又是這破烂%item_link', 'uf, otra vez esta basura %item_link', 'uf, otra vez esta basura %item_link', 'опять этот хлам %item_link'),
	(8, 'broadcast_looting_item_poor', 'seem to be looting trash %item_link', 0, 0, '쓰레기만 주울 것 같네 %item_link', 'Il semble que je fouille dans les ordures %item_link.', 'scheint so, als würde ich nur Müll looten: %item_link', '看来我捡的都是垃圾%item_link', '看來我捡的都是垃圾%item_link', 'parece que solo estoy saqueando basura %item_link', 'parece que solo estoy saqueando basura %item_link', 'похоже, я лутаю мусор %item_link'),
	(9, 'broadcast_looting_item_poor', 'well, it’s better than nothing I guess %item_link', 0, 0, '뭐, %item_link, 없는 것보단 낫지', 'Eh bien, c’est toujours mieux que rien, je suppose %item_link', 'naja, besser als nix, schätze ich: %item_link', '好吧，有%item_link总比没有强', '好吧，有%item_link總比沒有强', 'bueno, %item_link es mejor que nada supongo', 'bueno, %item_link es mejor que nada supongo', 'ну, лучше чем ничего, наверное %item_link'),
	(10, 'broadcast_looting_item_poor', 'not sure what to do with %item_link', 0, 0, '%item_link 뭐 하지?', 'Je ne suis pas certain de ce qu’il faut faire avec %item_link.', 'keine Ahnung, was ich mit %item_link anfangen soll', '不知道这%item_link能干啥', '不知道這%item_link能干啥', 'no sé qué hacer con %item_link', 'no sé qué hacer con %item_link', 'не знаю, что делать с %item_link'),
	(11, 'broadcast_looting_item_normal', 'well, I can keep looting %item_link all day', 0, 0, '%item_link 하루 종일 루팅해도 되겠다', 'Eh bien, je peux passer la journée à looter %item_link!', 'naja, ich kann den ganzen Tag %item_link looten', '好吧，我能捡%item_link捡一天', '好吧，我能捡%item_link捡一天', 'podría saquear %item_link todo el día', 'podría saquear %item_link todo el día', 'могу лутать %item_link весь день'),
	(12, 'broadcast_looting_item_normal', 'another day, another %item_link', 0, 0, '또 하루, 또 %item_link', 'Encore une journée, encore un %item_link', 'neuer Tag, neuer %item_link', '又是新的一天，又捡了个%item_link', '又是新的一天，又捡了個%item_link', 'otro día, otro %item_link', 'otro día, otro %item_link', 'еще один день, еще один %item_link'),
	(13, 'broadcast_looting_item_normal', 'looted some %item_link', 0, 0, '%item_link 좀 루팅함', 'J’ai pillé quelques %item_link.', 'hab %item_link gelootet', '捡了点%item_link', '捡了點%item_link', 'saqueé un poco de %item_link', 'saqueé un poco de %item_link', 'получил немного %item_link'),
	(14, 'broadcast_looting_item_normal', 'some %item_link is alright', 0, 0, '%item_link 정도는 괜찮지', 'Certains %item_link passent bien', 'ein %item_link ist okay', '有点%item_link还凑合', '有點%item_link還凑合', 'un poco de %item_link está bien', 'un poco de %item_link está bien', 'немного %item_link — это нормально'),
	(15, 'broadcast_looting_item_uncommon', 'not bad, I just got %item_link', 0, 0, '나쁘지 않네, %item_link 방금 득템', 'Pas mal du tout, je viens juste de recevoir %item_link', 'nicht schlecht, hab grad %item_link bekommen.', '不错，刚捡到个%item_link', '不错，刚捡到個%item_link', 'no está mal, acabo de conseguir %item_link', 'no está mal, acabo de conseguir %item_link', 'неплохо, только что получил %item_link'),
	(16, 'broadcast_looting_item_uncommon', 'just looted %item_link in %zone_name', 0, 0, '%zone_name 에서 %item_link 루팅함', 'Je viens de piller %item_link dans %zone_name.', 'gerade %item_link in %zone_name gelootet', '刚在%zone_name捡到个%item_link', '刚在%zone_name捡到個%item_link', 'acabo de saquear %item_link en %zone_name', 'acabo de saquear %item_link en %zone_name', 'только что залутал %item_link в %zone_name'),
	(17, 'broadcast_looting_item_uncommon', 'I could put that to good use %item_link', 0, 0, '%item_link 쓸모 있겠다', 'Je pourrais bien utiliser ça %item_link', 'kann ich gut gebrauchen, %item_link', '这%item_link我能派上用场', '這%item_link我能派上用场', 'le sacaré buen provecho a %item_link', 'le sacaré buen provecho a %item_link', 'могу найти применение %item_link'),
	(18, 'broadcast_looting_item_uncommon', 'money money money %item_link', 0, 0, '돈 돈 돈 %item_link', 'L’argent, l’argent, l’argent! %item_link', 'Gold, Gold, Gold: %item_link', '发财了发财了！%item_link', '发财了发财了！%item_link', 'dinero dinero dinero %item_link', 'dinero dinero dinero %item_link', 'деньги, деньги, деньги %item_link'),
	(19, 'broadcast_looting_item_uncommon', 'got %item_link', 0, 0, '%item_link 득템', 'J’ai eu %item_link.', 'hab %item_link bekommen', '拿到了%item_link', '拿到了%item_link', 'conseguí %item_link', 'conseguí %item_link', 'получил %item_link'),
	(20, 'broadcast_looting_item_rare', '%item_link is hunter bis', 0, 0, '%item_link 사냥꾼 bis다', 'Ah, %item_link c’est le meilleur équipement pour les chasseurs.', '%item_link ist BiS für Jäger', '%item_link简直是猎人的极品装备', '%item_link简直是獵人的极品裝備', '%item_link es bis para cazador', '%item_link es bis para cazador', '%item_link — лучший для охотника'),
	(21, 'broadcast_looting_item_rare', '%item_link is %my_class bis', 0, 0, '%item_link %my_class bis다', '%item_link est %my_class bis.', '%item_link ist BiS für %my_class', '%item_link对%my_class来说是极品', '%item_link對%my_class來說是极品', '%item_link es bis para %my_class', '%item_link es bis para %my_class', '%item_link — лучший для %my_class'),
	(22, 'broadcast_looting_item_rare', 'RNG is not bad today %item_link', 0, 0, '오늘 RNG 괜찮네 %item_link', 'La RNG n’est pas mauvaise aujourd’hui %item_link.', 'RNG meint es heute gut: %item_link', '今天人品不错，捡到个%item_link', '今天人品不错，捡到個%item_link', 'hoy la RNG no está mal %item_link', 'hoy la RNG no está mal %item_link', 'сегодня удача на моей стороне %item_link'),
	(23, 'broadcast_looting_item_rare', 'sweet %item_link, freshly looted', 0, 0, '좋다 %item_link, 갓 루팅', 'Doux %item_link, fraîchement looté', 'nice, %item_link frisch gelootet', '太棒了，新鲜出炉的%item_link', '太棒了，新鲜出炉的%item_link', 'dulce %item_link, recién saqueado', 'dulce %item_link, recién saqueado', 'классный %item_link, только что залутал'),
	(24, 'broadcast_looting_item_rare', 'wow, I just got %item_link', 0, 0, '와, %item_link 방금 득템', 'wow, je viens de recevoir %item_link', 'wow, hab gerade %item_link bekommen', '哇，我刚捡到个%item_link', '哇，我刚捡到個%item_link', 'wow, acabo de conseguir %item_link', 'wow, acabo de conseguir %item_link', 'вау, только что получил %item_link'),
	(25, 'broadcast_looting_item_rare', '%item_link is hunter bis', 0, 0, '%item_link 사냥꾼 bis지', 'Ah, %item_link, c’est le meilleur équipement pour les chasseurs.', '%item_link ist BiS für Jäger', '%item_link是猎人的顶级装备', '%item_link是獵人的顶级裝備', '%item_link es bis para cazador', '%item_link es bis para cazador', '%item_link — лучший для охотника'),
	(26, 'broadcast_looting_item_rare', '%item_link is %my_class bis', 0, 0, '%item_link %my_class bis지', '%item_link est %my_class bis.', '%item_link ist BiS für %my_class', '%item_link对%my_class来说是顶级货', '%item_link對%my_class來說是顶级貨', '%item_link es bis para %my_class', '%item_link es bis para %my_class', '%item_link — лучший для %my_class'),
	(27, 'broadcast_looting_item_rare', 'RNG is not bad today %item_link', 0, 0, '오늘 RNG 나쁘지 않네 %item_link', 'Aujourd’hui, la RNG n’est pas mauvaise %item_link.', 'RNG meint es heute gut: %item_link', '今天运气真好，捡到%item_link', '今天運气真好，捡到%item_link', 'hoy la RNG no está tan mal %item_link', 'hoy la RNG no está tan mal %item_link', 'сегодня удача на моей стороне %item_link'),
	(28, 'broadcast_looting_item_rare', 'sweet %item_link, freshly looted', 0, 0, '좋아 %item_link, 갓 루팅', 'Oh, %item_link, fraîchement pillé', 'nice, %item_link frisch gelootet', '太好了，刚捡到个%item_link', '太好了，刚捡到個%item_link', 'genial %item_link, recién saqueado', 'genial %item_link, recién saqueado', 'классный %item_link, только что залутал'),
	(29, 'broadcast_looting_item_epic', 'OMG, look at what I just got %item_link!!!', 0, 0, 'OMG 방금 %item_link 득템했어!!!', 'OMG, regardez ce que je viens d’obtenir %item_link !!!', 'OMG, guckt mal, was ich gerade bekommen hab: %item_link!!!', '天啊，快看我刚捡到的%item_link！！！', '天啊，快看我刚捡到的%item_link！！！', 'OMG, mirad lo que acabo de conseguir %item_link!!!', 'OMG, mirad lo que acabo de conseguir %item_link!!!', 'ОГО, посмотрите, что я только что получил %item_link!!!'),
	(30, 'broadcast_looting_item_legendary', 'No @#$@% way! This can not be, I got %item_link, this is insane', 0, 0, '말도 안 돼! %item_link 득템, 미쳤어 @#$@%', 'Pas moyen! Ça ne peut pas être vrai, j’ai obtenu %item_link, c’est fou!', 'Keine @#$@% Chance! Ich hab %item_link bekommen, Wahnsinn.', '不是吧！这不可能，我竟然捡到%item_link，太疯狂了！', '不是吧！這不可能，我竟然捡到%item_link，太疯狂了！', 'No @#$@% way! No puede ser, me salió %item_link, esto es una locura', 'No @#$@% way! No puede ser, me salió %item_link, esto es una locura', 'Нет @#$@%! Не может быть, я получил %item_link, это безумие'),
	(31, 'broadcast_looting_item_artifact', 'No @#$@% way! This can not be, I got %item_link, this is insane', 0, 0, '말도 안 돼! %item_link 득템, 미쳤어 @#$@%', 'Pas possible! Ça ne peut pas être vrai, j’ai eu %item_link, c’est fou', 'Keine @#$@% Chance! Das kann nicht sein - ich hab %item_link bekommen, völlig irre.', '天哪！这不可能，我拿到了%item_link，简直不敢相信！', '天哪！這不可能，我拿到了%item_link，简直不敢相信！', 'No @#$@% way! No puede ser, me salió %item_link, esto es una locura', 'No @#$@% way! No puede ser, me salió %item_link, esto es una locura', 'Нет @#$@%! Не может быть, я получил %item_link, это безумие'),
	(32, 'broadcast_looting_item_poor', 'Seriously? Another %item_link? My luck is broken.', 0, 0, '진짜? 또 %item_link? 운 다 썼나', 'Sérieusement? Encore un %item_link? La poisse me suit, c’est pas possible.', 'Im Ernst? Noch ein %item_link? Mein Glück ist kaputt.', '不是吧？又是个%item_link？我的运气真是烂透了。', '不是吧？又是個%item_link？我的運气真是烂透了。', '¿En serio? ¿Otro %item_link? Mi suerte está rota.', '¿En serio? ¿Otro %item_link? Mi suerte está rota.', 'Нет @#$@%! Не может быть, я получил %item_link, это безумие'),
	(33, 'broadcast_looting_item_poor', 'This %item_link is not even worth the pixels it’s printed on.', 0, 0, '%item_link 픽셀값도 안 나올 듯', 'Cet %item_link ne vaut même pas les pixels sur lesquels il est imprimé.', 'Dieser %item_link ist nicht mal die Pixel wert, auf denen er angezeigt wird.', '这%item_link连显示它的像素都不值。', '這%item_link連显示它的像素都不值。', 'Este %item_link ni siquiera vale los píxeles que ocupa.', 'Este %item_link ni siquiera vale los píxeles que ocupa.', 'Я только что взял %quest_link'),
	(34, 'broadcast_looting_item_poor', 'I got %item_link... Ugh, here we go again.', 0, 0, '%item_link 득템... 또 시작이네', 'J’ai de nouveau %item_link... Oh là là, c’est reparti.', 'Ich hab %item_link... ugh, schon wieder.', '我又捡到个%item_link...哎，又来了。', '我又捡到個%item_link...哎，又來了。', 'Me salió %item_link... ugh, otra vez.', 'Me salió %item_link... ugh, otra vez.', 'только что принял %quest_link'),
	(35, 'broadcast_looting_item_poor', 'I don’t even know why I’m picking up %item_link, it’s useless.', 0, 0, '%item_link 왜 주우지, 쓸모없는데', 'Je me demande pourquoi je prends %item_link, c’est inutile.', 'Keine Ahnung, warum ich %item_link überhaupt aufhebe, es ist nutzlos.', '我都不知道为啥要捡%item_link，完全没用。', '我都不知道為啥要捡%item_link，完全沒用。', 'Ni idea por qué recojo %item_link, es inútil.', 'Ni idea por qué recojo %item_link, es inútil.', '%quest_link попробую выполнить это задание'),
	(36, 'broadcast_looting_item_poor', 'Look at this shiny %item_link... too bad it’s garbage.', 0, 0, '반짝이는 %item_link... 아깝게 쓰레기네', 'Regarde ce magnifique %item_link... dommage que ce soit de la camelote.', 'Schaut euch diesen glänzenden %item_link an... schade, ist trotzdem Müll.', '看看这闪亮的%item_link...可惜就是个垃圾。', '看看這闪亮的%item_link...可惜就是個垃圾。', 'Mirad este %item_link brillante... qué pena que sea basura.', 'Mirad este %item_link brillante... qué pena que sea basura.', 'взял %quest_link в %zone_name'),
	(37, 'broadcast_looting_item_poor', 'This %item_link isn’t even worth the paper it’s written on.', 0, 0, '%item_link 종이값도 안 됨', '%item_link ne vaut même pas le papier sur lequel il est écrit.', 'Dieser %item_link ist nicht mal das Papier wert, auf dem er stehen würde.', '这%item_link连写它的羊皮纸都不值。', '這%item_link連写它的羊皮纸都不值。', 'Este %item_link ni vale el papel en el que está escrito.', 'Este %item_link ni vale el papel en el que está escrito.', 'Наконец-то закончил %quest_obj_name для %quest_link'),
	(38, 'broadcast_looting_item_poor', 'I guess %item_link is better than nothing? Barely.', 0, 0, '%item_link, 없는 것보단 낫지? 겨우', 'Je suppose que %item_link vaut mieux que rien ? À peine.', 'Ich schätze, %item_link ist besser als gar nix? Gerade so.', '我想%item_link总比没有强吧？勉强。', '我想%item_link總比沒有强吧？勉强。', 'Supongo que %item_link es mejor que nada, ¿no? Apenas.', 'Supongo que %item_link es mejor que nada, ¿no? Apenas.', 'наконец-то получил %quest_obj_available/%quest_obj_required %quest_obj_name для %quest_link'),
	(39, 'broadcast_looting_item_poor', 'Not sure what to do with %item_link, maybe I’ll just sell it for 1 silver.', 0, 0, '%item_link 뭐 하지, 1실버에 팔까', 'Je ne suis pas sûr de ce que faire avec %item_link, peut-être que je vais juste le vendre pour 1 pièce d’argent.', 'Kein Plan, was ich mit %item_link machen soll, vielleicht verkauf ich es für 1 Silber.', '不知道%item_link能干嘛，或许卖1个银币得了。', '不知道%item_link能干嘛，或许賣1個银幣得了。', 'No sé qué hacer con %item_link, igual lo vendo por 1 plata.', 'No sé qué hacer con %item_link, igual lo vendo por 1 plata.', '%quest_obj_full_formatted для %quest_link, наконец-то'),
	(40, 'broadcast_looting_item_poor', 'Another %item_link... well, at least I’m getting something.', 0, 0, '또 %item_link... 뭐, 뭐라도 득템했네', 'Encore un %item_link... eh bien, au moins je reçois quelque chose.', 'Noch ein %item_link... naja, immerhin krieg ich was.', '又是个%item_link...好吧，至少有点收获。', '又是個%item_link...好吧，至少有點收獲。', 'Otro %item_link... bueno, al menos saqué algo.', 'Otro %item_link... bueno, al menos saqué algo.', 'Ох, получил %quest_obj_available/%quest_obj_required %quest_obj_name для %quest_link'),
	(41, 'broadcast_looting_item_poor', 'I hope %item_link is actually worth something because it looks awful.', 0, 0, '%item_link 좀 값나면 좋겠는데 생김새가...', 'J’espère que %item_link vaut en fait quelque chose parce que ça a l’air affreux.', 'Hoffentlich ist %item_link was wert, es sieht nämlich furchtbar aus.', '希望%item_link能值点钱，因为它看起来真垃圾。', '希望%item_link能值點钱，因為它看起來真垃圾。', 'Ojalá %item_link valga algo, porque se ve fatal.', 'Ojalá %item_link valga algo, porque se ve fatal.', 'еще нужно %quest_obj_missing %quest_obj_name для %quest_link'),
	(42, 'broadcast_looting_item_poor', 'Is %item_link a joke? Someone’s laughing at me.', 0, 0, '%item_link 농담이야? 누가 웃고 있네', '%item_link c’est une blague ? Quelqu’un se moque de moi.', 'Ist %item_link ein Witz? Irgendwer lacht mich aus.', '这%item_link是开玩笑吗？谁在嘲笑我啊！', '這%item_link是開玩笑嗎？誰在嘲笑我啊！', '¿%item_link es broma? Alguien se ríe de mí.', '¿%item_link es broma? Alguien se ríe de mí.', '%quest_obj_full_formatted, все еще работаю над %quest_link'),
	(43, 'broadcast_looting_item_poor', 'Why do I keep getting %item_link... did I anger RNG?', 0, 0, '왜 자꾸 %item_link 만 나와... RNG 화났나', 'Pourquoi est-ce que je continue à obtenir %item_link... est-ce que j’ai fâché le RNG?', 'Warum krieg ich ständig %item_link... hab ich RNG verärgert?', '为啥我老是拿到%item_link……我是不是得罪了随机之神？', '為啥我老是拿到%item_link……我是不是得罪了隨机之神？', '¿Por qué sigo sacando %item_link...? ¿Enfadé a la RNG?', '¿Por qué sigo sacando %item_link...? ¿Enfadé a la RNG?', 'Наконец-то закончил с %item_link для %quest_link'),
	(44, 'broadcast_looting_item_poor', 'It’s like %item_link is following me around. I don’t want it!', 0, 0, '%item_link 따라다니는 것 같아, 싫어', 'C’est comme si %item_link me suivait partout. Je ne veux pas de ça !', 'Als würde %item_link mir nachlaufen. Ich will das nicht!', '这%item_link就像缠着我一样，我才不要呢！', '這%item_link就像缠着我一样，我才不要呢！', 'Es como si %item_link me siguiera. ¡No lo quiero!', 'Es como si %item_link me siguiera. ¡No lo quiero!', 'наконец-то получил %quest_obj_available/%quest_obj_required %item_link для %quest_link'),
	(45, 'broadcast_looting_item_poor', 'There’s %item_link, again. What a surprise.', 0, 0, '또 %item_link. 깜짝 놀랐네', 'Encore %item_link. Quelle surprise.', 'Da ist %item_link schon wieder. Was für eine Überraschung.', '又是%item_link，真是“惊喜”啊。', '又是%item_link，真是“惊喜”啊。', 'Otra vez %item_link. Qué sorpresa.', 'Otra vez %item_link. Qué sorpresa.', '%quest_obj_full_formatted для %quest_link, наконец-то'),
	(46, 'broadcast_looting_item_poor', 'I guess %item_link is good for vendor trash?', 0, 0, '%item_link 상점에 팔 만한가?', 'I présume qu’ %item_link est bon pour vendre à un marchand ?', 'Ich schätze, %item_link taugt als Händler-Müll?', '看来%item_link只能当垃圾卖给商人了？', '看來%item_link只能当垃圾賣給商人了？', '¿%item_link sirve para vender al mercader?', '¿%item_link sirve para vender al mercader?', 'Ох, получил %quest_obj_available/%quest_obj_required %item_link для %quest_link'),
	(47, 'broadcast_looting_item_poor', 'Noooo, not %item_link again! RNG, please!', 0, 0, '안 돼, 또 %item_link! RNG 제발!', 'Oh non, pas encore %item_link! RNG s’il te plaît!', 'Neeeein, nicht schon wieder %item_link! RNG, bitte!', '不！别又是%item_link！随机之神，求放过！', '不！别又是%item_link！隨机之神，求放过！', 'Noooo, ¡otra vez %item_link! ¡RNG, por favor!', 'Noooo, ¡otra vez %item_link! ¡RNG, por favor!', 'еще нужно %quest_obj_missing %item_link для %quest_link'),
	(48, 'broadcast_looting_item_poor', 'Well, at least %item_link isn’t completely useless, right?', 0, 0, '뭐, %item_link 완전 쓸모없진 않지?', 'Eh bien, au moins %item_link n’est pas complètement inutile, n’est-ce pas?', 'Naja, ganz nutzlos ist %item_link immerhin nicht, oder?', '好吧，至少%item_link还不算完全没用，对吧？', '好吧，至少%item_link還不算完全沒用，對吧？', 'Bueno, al menos %item_link no es del todo inútil, ¿no?', 'Bueno, al menos %item_link no es del todo inútil, ¿no?', '%quest_obj_full_formatted, все еще работаю над %quest_link'),
	(49, 'broadcast_looting_item_poor', 'Another %item_link? RNG, do you even care?', 0, 0, '또 %item_link? RNG, 신경 좀 써', 'Encore %item_link ? La RNG est-ce que ça te dit quelque chose au moins?', 'Noch ein %item_link? RNG, kümmert dich das überhaupt?', '又一个%item_link？随机之神，你在乎过我的感受吗？', '又一個%item_link？隨机之神，你在乎过我的感受嗎？', '¿Otro %item_link? RNG, ¿te importa en algo?', '¿Otro %item_link? RNG, ¿te importa en algo?', 'Не успел завершить %quest_link вовремя...'),
	(50, 'broadcast_looting_item_poor', 'Maybe %item_link will be worth something in 10 years.', 0, 0, '%item_link 10년 뒤엔 값나겠지', 'Peut-être que %item_link vaudra quelque chose dans 10 ans.', 'Vielleicht ist %item_link in 10 Jahren was wert.', '或许%item_link十年后能值点钱吧。', '或许%item_link十年后能值點钱吧。', 'Quizá %item_link valga algo dentro de 10 años.', 'Quizá %item_link valga algo dentro de 10 años.', 'Время для %quest_link вышло :('),
	(51, 'broadcast_looting_item_poor', 'I guess I’ll just admire how %item_link looks... and throw it away.', 0, 0, '%item_link 예쁘긴 한데... 버릴 거야', 'Je suppose que je vais juste admirer %item_link ... et le jeter.', 'Ich bewundere einfach mal, wie %item_link aussieht... und schmeiß es weg.', '我就欣赏一下%item_link的样子……然后扔了吧。', '我就欣赏一下%item_link的样子……然后扔了吧。', 'Admiraré cómo se ve %item_link... y lo tiraré.', 'Admiraré cómo se ve %item_link... y lo tiraré.', 'Я выполнил все задачи для %quest_link'),
	(52, 'broadcast_looting_item_poor', 'Who needs %item_link? Not me, that’s for sure.', 0, 0, '%item_link 누가 필요해? 난 아님', 'Qui a besoin de %item_link ? Pas moi en tout cas, ça c’est sûr.', 'Wer braucht %item_link? Ich sicher nicht.', '谁需要%item_link啊？反正我肯定不要。', '誰需要%item_link啊？反正我肯定不要。', '¿Quién necesita %item_link? Yo desde luego no.', '¿Quién necesita %item_link? Yo desde luego no.', 'Выполнил все задачи для %quest_link'),
	(53, 'broadcast_looting_item_poor', 'Maybe %item_link will be useful... just kidding, it’s trash.', 0, 0, '%item_link 쓸모 있을지도... 농담, 쓰레기야', 'Peut-être que %item_link sera utile... non, je plaisante, c’est nul.', 'Vielleicht ist %item_link nützlich... haha, doch nur Müll.', '也许%item_link有用……开玩笑的，就是个垃圾。', '也许%item_link有用……開玩笑的，就是個垃圾。', 'Quizá %item_link sirva... ja, es basura.', 'Quizá %item_link sirva... ja, es basura.', 'Скоро сдам %quest_link, только что закончил все задачи'),
	(54, 'broadcast_looting_item_poor', 'The universe has given me %item_link. Great.', 0, 0, '우주가 %item_link 줬네. 대단해', 'L’univers m’a donné %item_link. Génial.', 'Das Universum schenkt mir %item_link. Toll.', '宇宙赐予了我%item_link，棒极了。', '宇宙赐予了我%item_link，棒极了。', 'El universo me ha dado %item_link. Genial.', 'El universo me ha dado %item_link. Genial.', 'Да, наконец-то сдал %quest_link'),
	(55, 'broadcast_looting_item_poor', 'Well, I have %item_link. Can’t say I’m thrilled.', 0, 0, '%item_link 득템. 별로 기쁘진 않네', 'Eh bien, j’ai %item_link. Franchement, je ne suis pas super emballé.', 'Gut, ich hab %item_link. Begeistert bin ich nicht.', '好吧，我拿到了%item_link，可一点也高兴不起来。', '好吧，我拿到了%item_link，可一點也高兴不起來。', 'Bueno, tengo %item_link. No estoy emocionado.', 'Bueno, tengo %item_link. No estoy emocionado.', 'сдал %quest_link'),
	(56, 'broadcast_looting_item_poor', 'What am I even going to do with %item_link? Can’t even sell it.', 0, 0, '%item_link 뭐 하지, 팔지도 못해', 'Qu’est-ce que je vais bien pouvoir faire avec %item_link ? Je ne peux même pas le vendre.', 'Was soll ich überhaupt mit %item_link anfangen? Nicht mal verkaufbar.', '我拿%item_link能干啥？连卖都卖不掉。', '我拿%item_link能干啥？連賣都賣不掉。', '¿Qué hago con %item_link? Ni siquiera lo puedo vender.', '¿Qué hago con %item_link? Ni siquiera lo puedo vender.', 'смог завершить %quest_link, только что сдал'),
	(57, 'broadcast_looting_item_poor', 'Let’s add %item_link to my growing pile of disappointment.', 0, 0, '실망 더미에 %item_link 추가', 'Ajoutons %item_link à ma pile croissante de déceptions.', 'Packen wir %item_link zu meinem wachsenden Enttäuschungsstapel.', '把%item_link扔进我那堆失望的垃圾里吧。', '把%item_link扔進我那堆失望的垃圾里吧。', 'Añadamos %item_link a mi montón creciente de decepción.', 'Añadamos %item_link a mi montón creciente de decepción.', 'только что сдал %quest_link'),
	(58, 'broadcast_looting_item_poor', 'Thanks for %item_link... it’s exactly what I didn’t need.', 0, 0, '%item_link 고마워... 딱 필요 없던 거', 'Merci pour %item_link... c’est exactement ce qu’il me fallait pas.', 'Danke für %item_link... genau das, was ich nicht gebraucht hab.', '谢谢给了我%item_link……这正是我不需要的东西。', '谢谢給了我%item_link……這正是我不需要的东西。', 'Gracias por %item_link... justo lo que no necesitaba.', 'Gracias por %item_link... justo lo que no necesitaba.', 'только что сдал %quest_link в %zone_name'),
	(59, 'broadcast_looting_item_poor', 'Another %item_link... RNG, we need to talk.', 0, 0, '또 %item_link... RNG, 얘기 좀 하자', 'Encore un %item_link... RNG, on doit avoir une discussion.', 'Noch ein %item_link... RNG, wir müssen reden.', '又一个%item_link……随机之神，咱们得谈谈。', '又一個%item_link……隨机之神，咱們得谈谈。', 'Otro %item_link... RNG, tenemos que hablar.', 'Otro %item_link... RNG, tenemos que hablar.', 'еще одна жертва — %victim_name'),
	(60, 'broadcast_looting_item_poor', 'I’ve looted so many %item_link, I could open a store with them.', 0, 0, '%item_link 이렇게 많이 루팅했으면 가게 차려도 되겠다', 'J’ai récupéré tellement de %item_link, je pourrais ouvrir un magasin avec.', 'Ich hab so viele %item_link gelootet, ich könnte damit einen Laden aufmachen.', '我捡了这么多%item_link，够开个杂货铺了。', '我捡了這么多%item_link，够開個杂貨铺了。', 'He saqueado tantos %item_link que podría abrir una tienda.', 'He saqueado tantos %item_link que podría abrir una tienda.', 'Я продолжаю убивать %victim_name, нечего рассказывать'),
	(61, 'broadcast_looting_item_poor', 'A shiny %item_link... maybe for the trash pile.', 0, 0, '반짝이는 %item_link... 쓰레기통용', 'Un brillant %item_link... peut-être destiné à la poubelle.', 'Ein glänzender %item_link... kommt wohl auf den Müllhaufen.', '一个闪亮的%item_link……大概只能扔垃圾堆了。', '一個闪亮的%item_link……大概只能扔垃圾堆了。', 'Un %item_link brillante... para la basura, supongo.', 'Un %item_link brillante... para la basura, supongo.', 'еще один %victim_name пал'),
	(62, 'broadcast_looting_item_poor', 'It’s %item_link, everybody. Don’t get too excited.', 0, 0, '여러분, %item_link 입니다. 너무 신나지 마', 'C’est %item_link, tout le monde. Pas de quoi s’affoler.', 'Es ist %item_link, Leute. Nicht zu früh freuen.', '各位，这是%item_link，别太激动哦。', '各位，這是%item_link，别太激動哦。', 'Es %item_link, gente. No os emocionéis demasiado.', 'Es %item_link, gente. No os emocionéis demasiado.', 'минус один %victim_name в %zone_name'),
	(63, 'broadcast_looting_item_poor', 'Well, at least it’s %item_link... could be worse.', 0, 0, '뭐, %item_link... 더 나쁠 수도 있지', 'Eh bien, au moins c’est %item_link... ça pourrait être pire.', 'Naja, wenigstens ist es %item_link... könnte schlimmer sein.', '好吧，至少是%item_link……还能更糟呢。', '好吧，至少是%item_link……還能更糟呢。', 'Bueno, al menos es %item_link... podría ser peor.', 'Bueno, al menos es %item_link... podría ser peor.', 'Убил этого элитного ублюдка %victim_name!'),
	(64, 'broadcast_looting_item_poor', 'I’ll take %item_link over nothing.', 0, 0, '없는 것보단 %item_link 낫지', 'Je préfère %item_link à rien du tout.', 'Lieber %item_link als gar nix.', '有%item_link总比啥也没有强。', '有%item_link總比啥也沒有强。', 'Prefiero %item_link a no tener nada.', 'Prefiero %item_link a no tener nada.', 'убил элиту %victim_name в %zone_name'),
	(65, 'broadcast_looting_item_poor', 'Another %item_link. Not the worst.', 0, 0, '또 %item_link. 최악은 아님', 'Encore un %item_link. Pas le pire.', 'Noch ein %item_link. Nicht das Schlimmste.', '又一个%item_link，还不算最差。', '又一個%item_link，還不算最差。', 'Otro %item_link. No es lo peor.', 'Otro %item_link. No es lo peor.', 'Фух, удалось завалить %victim_name!'),
	(66, 'broadcast_looting_item_poor', 'Hey, %item_link... it’s okay, I suppose.', 0, 0, '%item_link... 그래, 괜찮은 것 같아', 'Salut, %item_link... c’est correct, je suppose.', 'Hey, %item_link... ist schon okay, denk ich.', '嘿，%item_link……还行吧，我觉得。', '嘿，%item_link……還行吧，我覺得。', 'Oye, %item_link... está bien, supongo.', 'Oye, %item_link... está bien, supongo.', 'Это было круто! Только что убил %victim_name! Теперь есть что рассказать'),
	(67, 'broadcast_looting_item_normal', 'Hey, %item_link. Not bad, not great, but I’ll take it.', 0, 0, '%item_link, 나쁘지도 좋지도 않네, 받을게', 'Salut, %item_link. Pas mal, pas super, mais je vais le prendre.', 'Hey, %item_link. Nicht schlecht, nicht gut, aber ich nehme es.', '嘿，%item_link。不算好也不算差，拿了再说。', '嘿，%item_link。不算好也不算差，拿了再說。', 'Oye, %item_link. Ni mal ni bien, me lo quedo.', 'Oye, %item_link. Ni mal ni bien, me lo quedo.', 'Йо, я только что убил %victim_name!'),
	(68, 'broadcast_looting_item_normal', 'Could be worse... I just looted %item_link.', 0, 0, '더 나쁠 수도... %item_link 루팅함', 'Ça aurait pu être pire... Je viens juste de mettre la main sur %item_link.', 'Könnte schlimmer sein... hab gerade %item_link gelootet.', '还行吧……刚捡到个%item_link。', '還行吧……刚捡到個%item_link。', 'Podría ser peor... acabo de saquear %item_link.', 'Podría ser peor... acabo de saquear %item_link.', 'убил редкого %victim_name в %zone_name'),
	(69, 'broadcast_looting_item_normal', 'I guess %item_link will come in handy for something.', 0, 0, '%item_link 어디선가 쓸모 있겠지', 'Je suppose que %item_link va être utile pour quelque chose.', '%item_link wird für irgendwas nützlich sein, denke ich.', '我觉得%item_link总能派上点用场。', '我覺得%item_link總能派上點用场。', 'Supongo que %item_link me servirá para algo.', 'Supongo que %item_link me servirá para algo.', 'Что я только что убил? %victim_name'),
	(70, 'broadcast_looting_item_normal', 'Another day, another %item_link. Can’t complain.', 0, 0, '또 하루, 또 %item_link. 불평할 건 없지', 'Encore une journée, encore un %item_link. Je ne vais pas me plaindre.', 'Neuer Tag, neuer %item_link. Kann mich nicht beschweren.', '又是新的一天，又捡到个%item_link，挺好。', '又是新的一天，又捡到個%item_link，挺好。', 'Otro día, otro %item_link. No me quejo.', 'Otro día, otro %item_link. No me quejo.', 'Только что убил этого пета %victim_name'),
	(71, 'broadcast_looting_item_normal', 'Well, %item_link is alright, I guess.', 0, 0, '%item_link 괜찮은 것 같아', 'Hmm, %item_link, c’est pas mal, je suppose.', 'Naja, %item_link geht klar, würd ich sagen.', '嗯，%item_link还行吧，我觉得。', '嗯，%item_link還行吧，我覺得。', 'Bueno, %item_link está bien, supongo.', 'Bueno, %item_link está bien, supongo.', 'О да, только что убил %victim_name'),
	(72, 'broadcast_looting_item_normal', 'Just got %item_link. It’s not the best, but it’s something.', 0, 0, '%item_link 득템. 최고는 아니지만 뭐', 'Je viens de récupérer %item_link. Ce n’est pas le meilleur, mais c’est mieux que rien.', 'Gerade %item_link bekommen. Nicht das Beste, aber etwas.', '刚拿到%item_link，不是最好的，但也算有点收获。', '刚拿到%item_link，不是最好的，但也算有點收獲。', 'Acabo de conseguir %item_link. No es lo mejor, pero algo es.', 'Acabo de conseguir %item_link. No es lo mejor, pero algo es.', 'убил %victim_name в %zone_name'),
	(73, 'broadcast_looting_item_normal', 'Could be worse, at least it’s %item_link.', 0, 0, '더 나쁠 수도, 적어도 %item_link', 'Ça pourrait être pire, au moins c’est %item_link.', 'Könnte schlimmer sein, immerhin ist es %item_link.', '还能更糟呢，至少是%item_link。', '還能更糟呢，至少是%item_link。', 'Podría ser peor, al menos es %item_link.', 'Podría ser peor, al menos es %item_link.', 'Динг!'),
	(74, 'broadcast_looting_item_normal', '%item_link is good enough, I’m not mad.', 0, 0, '%item_link, 충분해, 짜증 안 나', '%item_link est assez bon, je ne suis pas fâché.', '%item_link ist gut genug, ich bin nicht sauer.', '%item_link还不错，我没啥好抱怨的。', '%item_link還不错，我沒啥好抱怨的。', '%item_link está bien, no me enfado.', '%item_link está bien, no me enfado.', 'Да, я теперь %my_level уровень!'),
	(75, 'broadcast_looting_item_normal', 'It’s no legendary, but %item_link will do.', 0, 0, '전설은 아니지만 %item_link 로 됐어', 'Ce n’est pas légendaire, mais %item_link fera l’affaire.', 'Kein Legendary, aber %item_link reicht.', '虽然不是传说装备，但%item_link也凑合了。', '虽然不是傳說裝備，但%item_link也凑合了。', 'No es legendario, pero %item_link sirve.', 'No es legendario, pero %item_link sirve.', 'Я только что повысил уровень'),
	(76, 'broadcast_looting_item_normal', 'Not a bad drop... %item_link is alright.', 0, 0, '나쁘지 않은 드롭... %item_link 괜찮네', 'Pas mal du tout cette trouvaille... %item_link est pas mal du tout.', 'Kein schlechter Drop... %item_link ist okay.', '掉落还行……%item_link不错。', '掉落還行……%item_link不错。', 'No está mal el drop... %item_link está bien.', 'No está mal el drop... %item_link está bien.', 'Я %my_level уровень!!!'),
	(77, 'broadcast_looting_item_normal', 'I’ll take %item_link over nothing.', 0, 0, '없는 것보단 %item_link', 'Je préfère %item_link à rien du tout.', 'Lieber %item_link als gar nix.', '有%item_link总比啥也没有强。', '有%item_link總比啥也沒有强。', 'Prefiero %item_link a no tener nada.', 'Prefiero %item_link a no tener nada.', 'Становлюсь сильнее, уже %my_level уровень!!!'),
	(78, 'broadcast_looting_item_normal', 'Not the best, but %item_link is a nice addition.', 0, 0, '최고는 아니지만 %item_link 괜찮은 추가템', 'Ce n’est pas le meilleur, mais %item_link est une belle addition.', 'Nicht das Beste, aber %item_link ist eine nette Ergänzung.', '不是最好的，但%item_link也是个不错的收获。', '不是最好的，但%item_link也是個不错的收獲。', 'No es lo mejor, pero %item_link es una buena adición.', 'No es lo mejor, pero %item_link es una buena adición.', 'Только что достиг %my_level уровня!!!'),
	(79, 'broadcast_looting_item_normal', 'Getting %item_link again. I guess it’s better than nothing.', 0, 0, '또 %item_link. 없는 것보단 낫지', 'Encore en train de récupérer %item_link. Je suppose que c’est mieux que rien.', 'Schon wieder %item_link. Besser als nix, denke ich.', '又拿了个%item_link，总比啥也没有好。', '又拿了個%item_link，總比啥也沒有好。', 'Otra vez %item_link. Mejor que nada, supongo.', 'Otra vez %item_link. Mejor que nada, supongo.', 'ОГО, наконец-то %my_level уровень!!!'),
	(80, 'broadcast_looting_item_normal', '%item_link again, huh? I’m not thrilled, but I’ll live.', 0, 0, '또 %item_link? 별로지만 살 만해', 'Encore %item_link, hein? Je ne suis pas super enthousiaste, mais bon, je vais m’en sortir.', '%item_link schon wieder, hm? Nicht begeistert, aber ich überlebe.', '又是%item_link？不太激动，不过还能接受。', '又是%item_link？不太激動，不过還能接受。', '¿Otra vez %item_link? No me emociona, pero sobreviviré.', '¿Otra vez %item_link? No me emociona, pero sobreviviré.', '%my_level!!! теперь могу заниматься эндгейм-контентом'),
	(81, 'broadcast_looting_item_normal', 'Another %item_link? I’m okay with that.', 0, 0, '또 %item_link? 괜찮아', 'Encore un %item_link? Ça me va.', 'Noch ein %item_link? Passt schon.', '又一个%item_link？我觉得还行。', '又一個%item_link？我覺得還行。', '¿Otro %item_link? Me vale.', '¿Otro %item_link? Me vale.', 'свежий новый уровень %my_level %my_class!!!'),
	(82, 'broadcast_looting_item_normal', 'Could’ve gotten worse, but %item_link isn’t so bad.', 0, 0, '더 나빠질 수도 있었는데 %item_link 나쁘지 않네', 'Ça aurait pu être pire, mais %item_link n’est pas si mal.', 'Hätte schlimmer kommen können, %item_link ist gar nicht so schlecht.', '本来可能更糟，但%item_link还算可以。', '本來可能更糟，但%item_link還算可以。', 'Podría haber sido peor, %item_link no está tan mal.', 'Podría haber sido peor, %item_link no está tan mal.', 'еще один уровень %my_level %my_race %my_class!'),
	(83, 'broadcast_looting_item_normal', 'It’s %item_link... but at least it’s something.', 0, 0, '%item_link... 뭐, 뭐라도 있으니까', 'C’est %item_link... mais au moins c’est quelque chose.', 'Es ist %item_link... aber immerhin etwas.', '是%item_link……但至少是个东西。', '是%item_link……但至少是個东西。', 'Es %item_link... pero al menos es algo.', 'Es %item_link... pero al menos es algo.', 'Молодец %other_name. Ты это заслужил.'),
	(84, 'broadcast_looting_item_normal', 'I’ll take %item_link, could be worse.', 0, 0, '%item_link 받을게, 더 나쁠 수도 있지', 'Je vais prendre %item_link, ça aurait pu être pire.', 'Ich nehm %item_link, könnte schlimmer sein.', '我就拿%item_link吧，总比更糟的好。', '我就拿%item_link吧，總比更糟的好。', 'Me quedo %item_link, podría ser peor.', 'Me quedo %item_link, podría ser peor.', 'Это было ужасно %other_name. Не хотел этого делать, но...'),
	(85, 'broadcast_looting_item_normal', 'Looted %item_link, nothing special but okay.', 0, 0, '%item_link 루팅, 특별하진 않지만 ok', 'J’ai pillé %item_link, rien de spécial mais bon.', '%item_link gelootet, nix Besonderes, aber okay.', '捡了个%item_link，没啥特别的，但还行。', '捡了個%item_link，沒啥特别的，但還行。', 'Saqué %item_link, nada especial pero ok.', 'Saqué %item_link, nada especial pero ok.', 'Кому нужен %instance_name?'),
	(86, 'broadcast_looting_item_normal', 'Not what I wanted, but %item_link will do for now.', 0, 0, '원하던 건 아니지만 %item_link 일단 쓸게', 'Ce n’est pas exactement ce que je voulais, mais %item_link fera l’affaire pour l’instant.', 'Nicht das, was ich wollte, aber %item_link reicht fürs Erste.', '不是我想要的，但%item_link先凑合用吧。', '不是我想要的，但%item_link先凑合用吧。', 'No era lo que quería, pero %item_link me vale por ahora.', 'No era lo que quería, pero %item_link me vale por ahora.', 'Есть группы в %instance_name?'),
	(87, 'broadcast_looting_item_normal', 'Another %item_link. Not amazing, but it’ll do.', 0, 0, '또 %item_link. 대단하진 않지만 됐어', 'Encore un %item_link. Pas extraordinaire, mais ça fera l’affaire.', 'Noch ein %item_link. Nicht der Wahnsinn, aber geht klar.', '又一个%item_link，不算惊艳，但能用。', '又一個%item_link，不算惊艳，但能用。', 'Otro %item_link. No es increíble, pero sirve.', 'Otro %item_link. No es increíble, pero sirve.', 'Нужна помощь в %instance_name?'),
	(88, 'broadcast_looting_item_normal', 'Looted %item_link, could be worse.', 0, 0, '%item_link 루팅, 더 나쁠 수도 있었지', 'J’ai pillé %item_link, ça aurait pu être pire.', '%item_link gelootet, könnte schlimmer sein.', '捡了个%item_link，还不算太糟。', '捡了個%item_link，還不算太糟。', 'Saqué %item_link, podría haber sido peor.', 'Saqué %item_link, podría haber sido peor.', 'ЛФД: %instance_name.'),
	(89, 'broadcast_looting_item_normal', 'Well, %item_link is better than a poke in the eye.', 0, 0, '%item_link, 눈 찌르는 것보단 낫지', 'Eh bien, %item_link vaut mieux que de se faire poke dans l’œil.', 'Naja, %item_link ist besser als ein Stich ins Auge.', '好吧，%item_link总比被戳眼强。', '好吧，%item_link總比被戳眼强。', 'Bueno, %item_link es mejor que un poco en el ojo.', 'Bueno, %item_link es mejor que un poco en el ojo.', 'Кому нужен %my_role для %instance_name?'),
	(90, 'broadcast_looting_item_normal', 'I’ll take %item_link and move on.', 0, 0, '%item_link 챙기고 갈게', 'Je vais prendre %item_link et continuer.', 'Ich nehm %item_link und zieh weiter.', '拿上%item_link，继续前行吧。', '拿上%item_link，继續前行吧。', 'Me quedo %item_link y sigo.', 'Me quedo %item_link y sigo.', 'Не хватает %my_role для %instance_name?'),
	(91, 'broadcast_looting_item_uncommon', 'Nice! A solid %item_link for the collection.', 0, 0, '좋아! %item_link 컬렉션에 딱', 'Super! Un bel %item_link pour la collection.', 'Nice! Ein solider %item_link für die Sammlung.', '不错！一个靠谱的%item_link，收好了！', '不错！一個靠谱的%item_link，收好了！', '¡Bien! Un buen %item_link para la colección.', '¡Bien! Un buen %item_link para la colección.', 'Могу быть %my_role для %instance_name.'),
	(92, 'broadcast_looting_item_uncommon', 'I’ll take that %item_link any day.', 0, 0, '%item_link 언제든 환영', 'Je prendrais bien ce lien de %item_link n’importe quel jour.', 'Den %item_link nehm ich jederzeit.', '这%item_link我随时都乐意拿！', '這%item_link我隨時都乐意拿！', 'Me quedo ese %item_link cualquier día.', 'Me quedo ese %item_link cualquier día.', 'Нужна помощь с %instance_name?'),
	(93, 'broadcast_looting_item_uncommon', 'Not bad, %item_link might come in handy.', 0, 0, '나쁘지 않네, %item_link 쓸모 있을 듯', 'Pas mal, %item_link pourrait s’avérer utile.', 'Nicht schlecht, %item_link könnte nützlich werden.', '还不错，%item_link说不定能派上用场。', '還不错，%item_link說不定能派上用场。', 'No está mal, %item_link puede ser útil.', 'No está mal, %item_link puede ser útil.', 'Нужна помощь %my_role с %instance_name?'),
	(94, 'broadcast_looting_item_uncommon', 'Got myself a %item_link, now we’re talking.', 0, 0, '%item_link 득템, 이제 얘기가 달라지네', 'Je me suis procuré %item_link, ça va être la folie maintenant !', 'Hab mir %item_link geholt, jetzt gehts los.', '搞到个%item_link，这下有戏了！', '搞到個%item_link，這下有戏了！', 'Conseguí %item_link, ahora sí hablamos.', 'Conseguí %item_link, ahora sí hablamos.', 'Кому нужен шмот из %instance_name?'),
	(95, 'broadcast_looting_item_uncommon', 'That %item_link is better than most, I’ll take it.', 0, 0, '그 %item_link 대부분보다 낫네, 받을게', 'Ce %item_link est meilleur que la plupart, je vais le prendre.', 'Dieser %item_link ist besser als die meisten, nehm ich.', '这%item_link比大多数都好，我收下了！', '這%item_link比大多数都好，我收下了！', 'Ese %item_link es mejor que la mayoría, me lo quedo.', 'Ese %item_link es mejor que la mayoría, me lo quedo.', 'Немного пофармить в %instance_name?'),
	(96, 'broadcast_looting_item_uncommon', 'I could use %item_link for something good.', 0, 0, '%item_link 좋은 데 쓸 수 있겠다', 'Je pourrais utiliser %item_link pour quelque chose de bien.', 'Mit %item_link kann ich was Gutes anfangen.', '我能用%item_link干点好事。', '我能用%item_link干點好事。', 'Puedo usar %item_link para algo bueno.', 'Puedo usar %item_link para algo bueno.', 'Ищу %instance_name'),
	(97, 'broadcast_looting_item_uncommon', 'Not bad, %item_link will work just fine.', 0, 0, '나쁘지 않아, %item_link 딱 좋아', 'Pas mal, %item_link va parfaitement convenir.', 'Nicht schlecht, %item_link passt schon.', '不错，%item_link用起来正好。', '不错，%item_link用起來正好。', 'No está mal, %item_link me va perfecto.', 'No está mal, %item_link me va perfecto.', 'Нужна помощь в %instance_name.'),
	(98, 'broadcast_looting_item_uncommon', 'Another %item_link, at least it’s not useless.', 0, 0, '또 %item_link, 적어도 쓸모는 있지', 'Encore un %item_link, au moins ce n’est pas inutile.', 'Noch ein %item_link, immerhin nicht nutzlos.', '又一个%item_link，至少不是没用的。', '又一個%item_link，至少不是沒用的。', 'Otro %item_link, al menos no es inútil.', 'Otro %item_link, al menos no es inútil.', 'Хочу пройти %instance_name.'),
	(99, 'broadcast_looting_item_uncommon', 'That %item_link might make a decent profit.', 0, 0, '그 %item_link 꽤 팔리겠는데', 'Ce  %item_link pourrait me rapporter un joli profit.', 'Mit %item_link lässt sich vielleicht gut verdienen.', '这%item_link说不定能卖个好价钱。', '這%item_link說不定能賣個好价钱。', 'Ese %item_link puede dar buen beneficio.', 'Ese %item_link puede dar buen beneficio.', '%my_role ищет %instance_name.'),
	(100, 'broadcast_looting_item_uncommon', 'A solid %item_link, now the day is looking better.', 0, 0, '탄탄한 %item_link, 오늘 기분 좋아지네', 'Un bon %item_link, ça rend la journée plus belle maintenant.', 'Ein solider %item_link, der Tag sieht gleich besser aus.', '一个靠谱的%item_link，今天心情都变好了。', '一個靠谱的%item_link，今天心情都变好了。', 'Un buen %item_link, el día ya se ve mejor.', 'Un buen %item_link, el día ya se ve mejor.', 'Как насчет %instance_name?'),
	(101, 'broadcast_looting_item_uncommon', 'Well, I didn’t expect %item_link, but I’ll take it.', 0, 0, '%item_link 예상 못 했는데 받을게', 'Eh bien, je ne m’attendais pas à %item_link, mais je vais le prendre.', 'Hab %item_link nicht erwartet, aber ich nehm es.', '嗯，没想到会拿到%item_link，但我收下了。', '嗯，沒想到會拿到%item_link，但我收下了。', 'No esperaba %item_link, pero me lo quedo.', 'No esperaba %item_link, pero me lo quedo.', 'Кто хочет пофармить %instance_name?'),
	(102, 'broadcast_looting_item_uncommon', 'Not sure what to do with %item_link, but I’m happy to have it.', 0, 0, '%item_link 뭐 하지 모르겠지만 기분 좋네', 'Je ne suis pas sûr de ce qu’il faut faire avec %item_link, mais je suis content de l’avoir.', 'Kein Plan, was ich mit %item_link machen soll aber ich freue mich drüber.', '不太确定%item_link干啥用，但我很开心能拿到。', '不太确定%item_link干啥用，但我很開心能拿到。', 'No sé qué hacer con %item_link, pero me alegra tenerlo.', 'No sé qué hacer con %item_link, pero me alegra tenerlo.', 'Пойдем в %instance_name?'),
	(103, 'broadcast_looting_item_uncommon', 'Not my first choice, but I’ll happily accept %item_link.', 0, 0, '1순위는 아니지만 %item_link 기꺼이 받을게', 'Ce n’était pas mon premier choix, mais je vais volontiers accepter %item_link.', 'Nicht meine erste Wahl, aber %item_link nehm ich gern.', '不是我的首选，但我很乐意收下%item_link。', '不是我的首選，但我很乐意收下%item_link。', 'No era mi primera opción, pero acepto %item_link con gusto.', 'No era mi primera opción, pero acepto %item_link con gusto.', 'Ищу %instance_name.'),
	(104, 'broadcast_looting_item_uncommon', 'That %item_link is exactly what I needed today.', 0, 0, '그 %item_link 오늘 딱 필요했어', 'Ce %item_link est exactement ce dont j’avais besoin aujourd’hui.', 'Genau das hab ich heute gebraucht: %item_link.', '这%item_link正是我今天需要的！', '這%item_link正是我今天需要的！', 'Ese %item_link es justo lo que necesitaba hoy.', 'Ese %item_link es justo lo que necesitaba hoy.', 'Нужна помощь с квестами в %instance_name?'),
	(105, 'broadcast_looting_item_uncommon', 'I’ll never say no to a nice %item_link.', 0, 0, '좋은 %item_link, 절대 거절 안 해', 'Je ne dis jamais non à une belle %item_link.', 'Zu einem schönen %item_link sag ich nie nein.', '对一个不错的%item_link，我从不说不。', '對一個不错的%item_link，我從不說不。', 'Nunca digo que no a un buen %item_link.', 'Nunca digo que no a un buen %item_link.', 'Хочу квестить в %instance_name.'),
	(106, 'broadcast_looting_item_uncommon', 'Another %item_link. I’ll take it, no complaints here.', 0, 0, '또 %item_link. 불평 없음', 'Encore un %item_link. Je le prends, pas de soucis ici.', 'Noch ein %item_link. Nehm ich, keine Beschwerden.', '又一个%item_link，我收下，没啥好抱怨的。', '又一個%item_link，我收下，沒啥好抱怨的。', 'Otro %item_link. Me lo quedo, sin quejas.', 'Otro %item_link. Me lo quedo, sin quejas.', 'Кто-то с квестами в %instance_name?'),
	(107, 'broadcast_looting_item_uncommon', 'At least %item_link has some use. Not the worst loot.', 0, 0, '적어도 %item_link, 쓸모 있지. 최악 드롭은 아님', 'Au moins %item_link a une certaine utilité. Ce n’est pas le pire butin.', 'Immerhin hat %item_link irgendeinen Nutzen. Nicht der schlimmste Loot.', '至少%item_link有点用，不是最差的战利品。', '至少%item_link有點用，不是最差的戰利品。', 'Al menos %item_link sirve para algo. No es el peor loot.', 'Al menos %item_link sirve para algo. No es el peor loot.', 'Могу помочь с квестами в %instance_name.'),
