	(113, 'broadcast_quest_accepted_generic', 'I just picked up %quest_link, time to get to work!', 0, 0, '%quest_link 방금 받았어, 일 시작!', 'Je viens de prendre %quest_link, c’est parti pour se mettre au travail !', 'Gerade %quest_link abgeholt, Zeit ranzuklotzen!', '刚接到%quest_link，是时候开干了！', '刚接到%quest_link，是時候開干了！', 'Acabo de coger %quest_link, ¡a currar!', 'Acabo de coger %quest_link, ¡a currar!', 'Кому нужны еще люди для %instance_name?'),
