	(122, 'broadcast_quest_accepted_generic', 'On my way to complete %quest_link. Here we go!', 0, 0, '%quest_link 완료하러 가는 중. 출발!', 'En route pour terminer ma quête %quest_link! C’est parti!', 'Unterwegs, %quest_link abzuschließen. Auf gehts!', '正在赶去完成%quest_link，走起！', '正在赶去完成%quest_link，走起！', 'De camino a completar %quest_link. ¡Vamos!', 'De camino a completar %quest_link. ¡Vamos!', 'Хочу полный забег %instance_name'),
