	(333, 'broadcast_levelup_max_level', 'Max level %my_level, endgame here I come!', 0, 0, '맥스 레벨 %my_level, 엔드게임 간다!', 'Niveau maximum %my_level atteint, je me rapproche de la fin du jeu !', 'Maxlevel %my_level, Endgame ich komme!', '满级%my_level，终极挑战我来了！', '满级%my_level，终极挑戰我來了！', '¡Nivel máximo %my_level, endgame aquí voy!', '¡Nivel máximo %my_level, endgame aquí voy!', 'крутой стояк, бро'),
	(334, 'broadcast_levelup_max_level', 'Level %my_level! Ready for the endgame!', 0, 0, '레벨 %my_level! 엔드게임 준비!', 'Niveau %my_level ! Prêt pour la phase finale !', 'Level %my_level! Bereit fürs Endgame!', '%my_level级达成！准备好迎接终极内容了！', '%my_level级达成！准備好迎接终极内容了！', '¡Nivel %my_level! ¡Listo para el endgame!', '¡Nivel %my_level! ¡Listo para el endgame!', 'ERP?'),
	(335, 'broadcast_levelup_max_level', 'Endgame unlocked at level %my_level, bring it on!', 0, 0, '레벨 %my_level, 엔드게임 해금, 덤벼!', 'Fin du jeu débloquée au niveau %my_level, ça va déménager !', 'Endgame freigeschaltet auf Level %my_level, her damit!', '%my_level级解锁终极内容，来吧，挑战我！', '%my_level级解鎖终极内容，來吧，挑戰我！', '¡Endgame desbloqueado en nivel %my_level, tráelo!', '¡Endgame desbloqueado en nivel %my_level, tráelo!', 'я перепробовал все, но в итоге ERP помог'),
	(336, 'broadcast_levelup_max_level', 'I’ve reached level %my_level, time to shine!', 0, 0, '레벨 %my_level 달성, 빛날 시간!', 'J’ai atteint le niveau %my_level, c’est le moment de briller!', 'Hab Level %my_level erreicht, Zeit zu glänzen!', '我达到%my_level级了，是时候大放异彩了！', '我达到%my_level级了，是時候大放异彩了！', '¡Llegué a nivel %my_level, hora de brillar!', '¡Llegué a nivel %my_level, hora de brillar!', 'Хочу заняться этим в %zone_name'),
	(337, 'broadcast_levelup_max_level', 'Level %my_level, let’s do some endgame raiding!', 0, 0, '레벨 %my_level, 엔드게임 레이드 가자!', 'Niveau %my_level, allons faire un raid de fin de jeu!', 'Level %my_level, lasst uns Endgame-Raids machen!', '%my_level级了，咱去刷终极团队副本吧！', '%my_level级了，咱去刷终极團隊副本吧！', '¡Nivel %my_level, vamos a raids endgame!', '¡Nivel %my_level, vamos a raids endgame!', 'ищу гнома-девушку с гориллой для ERP в %zone_name'),
	(338, 'broadcast_levelup_max_level', 'At level %my_level, nothing can stop me now!', 0, 0, '레벨 %my_level, 이제 아무도 못 막아!', 'Au niveau %my_level, rien ne peut m’arrêter maintenant !', 'Mit Level %my_level hält mich nix mehr auf!', '在%my_level级，谁也挡不住我了！', '在%my_level级，誰也挡不住我了！', '¡En nivel %my_level, nada me detiene!', '¡En nivel %my_level, nada me detiene!', 'я могу понять засранца, но извращенца?'),
	(339, 'broadcast_levelup_max_level', 'Level %my_level, all systems go for high-level content!', 0, 0, '레벨 %my_level, 고레벨 콘텐츠 올 시스템 고!', 'Niveau %my_level, toutes les systèmes sont prêts pour du contenu de haut niveau !', 'Level %my_level, bereit für High-Level-Content!', '%my_level级，一切就绪，准备迎接高难度内容！', '%my_level级，一切就绪，准備迎接高難度内容！', '¡Nivel %my_level, todos los sistemas listos para high-level!', '¡Nivel %my_level, todos los sistemas listos para high-level!', 'в %zone_name нет гят'),
	(340, 'broadcast_levelup_max_level', 'Yes! Level %my_level, %my_class ready for everything!', 0, 0, '예! 레벨 %my_level, %my_class 뭐든 준비!', 'Oui! Niveau %my_level, %my_class prêt pour tout!', 'Yes! Level %my_level, %my_class für alles bereit!', '太棒了！%my_level级，我的%my_class准备好面对一切了！', '太棒了！%my_level级，我的%my_class准備好面對一切了！', '¡Sí! Nivel %my_level, %my_class listo para todo!', '¡Sí! Nivel %my_level, %my_class listo para todo!', 'Я убиваю всех животных в %zone_name. К черту животных!!!'),
	(341, 'broadcast_levelup_max_level', 'Level %my_level, it’s time to take on the world!', 0, 0, '레벨 %my_level, 세계 정복할 시간!', 'Niveau %my_level, c’est le moment de conquérir le monde!', 'Level %my_level, Zeit die Welt herauszufordern!', '%my_level级，是时候征服这个世界了！', '%my_level级，是時候征服這個世界了！', '¡Nivel %my_level, hora de conquistar el mundo!', '¡Nivel %my_level, hora de conquistar el mundo!', 'хорошо, что у меня три ноги'),
	(342, 'broadcast_levelup_max_level', 'Reached level %my_level, let’s take on those elite bosses!', 0, 0, '레벨 %my_level 달성, 엘리트 보스 가자!', 'J’ai atteint le niveau %my_level, allons affronter ces boss d’élite!', 'Level %my_level erreicht, schnappen wir uns die Elitebosse!', '达到%my_level级了，咱们去挑战那些精英首领吧！', '达到%my_level级了，咱們去挑戰那些精英首领吧！', '¡Nivel %my_level alcanzado, a por esos bosses élite!', '¡Nivel %my_level alcanzado, a por esos bosses élite!', 'не злись, я гоиню как сигма'),
	(343, 'broadcast_levelup_max_level', 'Now I’m %my_level, the real adventure begins!', 0, 0, '이제 레벨 %my_level, 진짜 모험 시작!', 'Maintenant que je suis %my_level, la vraie aventure commence!', 'Jetzt bin ich Level %my_level, das echte Abenteuer beginnt!', '现在我是%my_level级，真正的冒险才刚刚开始！', '現在我是%my_level级，真正的冒险才刚刚開始！', '¡Ahora soy %my_level, la aventura de verdad empieza!', '¡Ahora soy %my_level, la aventura de verdad empieza!', 'попробуй палец, но дырку'),
	(344, 'broadcast_levelup_max_level', 'Level %my_level! Time for some serious action!', 0, 0, '레벨 %my_level! 본격 액션 시간!', 'Niveau %my_level ! Il est temps d’entrer en action sérieusement !', 'Level %my_level! Zeit für ernsthafte Action!', '%my_level级！是时候来点硬核行动了！', '%my_level级！是時候來點硬核行動了！', '¡Nivel %my_level! ¡Hora de acción en serio!', '¡Nivel %my_level! ¡Hora de acción en serio!', '%prefix %random_taken_quest_or_item_link'),
	(345, 'broadcast_levelup_max_level', 'Level %my_level and still growing stronger!', 0, 0, '레벨 %my_level, 계속 더 강해지는 중!', 'Niveau %my_level et je continue de devenir de plus en plus fort !', 'Level %my_level und werde immer stärker!', '%my_level级了，而且我还会变得更强！', '%my_level级了，而且我還會变得更强！', '¡Nivel %my_level y sigo creciendo!', '¡Nivel %my_level y sigo creciendo!', '%prefix %random_inventory_item_link'),
	(346, 'broadcast_levelup_max_level', 'Finally at level %my_level! Let’s show off what I can do!', 0, 0, '드디어 레벨 %my_level! 실력 보여주자!', 'Enfin, je suis au niveau %my_level ! Il est temps de montrer de quoi je suis capable !', 'Endlich auf Level %my_level! Jetzt zeige ich, was ich kann!', '终于到%my_level级了！让大家看看我的厉害！', '终于到%my_level级了！让大家看看我的厉害！', '¡Por fin nivel %my_level! ¡A demostrar lo que puedo!', '¡Por fin nivel %my_level! ¡A demostrar lo que puedo!', '%thunderfury_link'),
	(347, 'broadcast_levelup_max_level', 'Level %my_level is here! I’m ready for the big leagues!', 0, 0, '레벨 %my_level 왔다! 빅리그 준비!', 'Le niveau %my_level est arrivé! Je suis prêt pour les grands matchs!', 'Level %my_level ist da! Bereit für die große Liga!', '%my_level级来了！我准备好迎接大挑战了！', '%my_level级來了！我准備好迎接大挑戰了！', '¡Llegó el nivel %my_level! ¡Listo para la gran liga!', '¡Llegó el nivel %my_level! ¡Listo para la gran liga!', '%thunderfury_link%thunderfury_link'),
	(348, 'broadcast_levelup_max_level', 'Just hit %my_level, get ready for the real challenges!', 0, 0, '방금 %my_level, 진짜 도전 준비해!', 'Je viens d’atteindre mon niveau %my_level, je suis prêt pour affronter de vrais défis !', 'Gerade Level %my_level erreicht, macht euch bereit für echte Herausforderungen!', '刚到%my_level级，准备好迎接真正的挑战吧！', '刚到%my_level级，准備好迎接真正的挑戰吧！', '¡Acabo de llegar a %my_level, prepárense para los retos de verdad!', '¡Acabo de llegar a %my_level, prepárense para los retos de verdad!', '%thunderfury_link%thunderfury_link%thunderfury_link'),
	(349, 'broadcast_levelup_max_level', 'Level %my_level complete, it’s time for the epic content!', 0, 0, '레벨 %my_level 완료, 에픽 콘텐츠 시간!', 'Niveau %my_level complet, il est temps pour le contenu épique !', 'Level %my_level voll, Zeit für epischen Content!', '%my_level级达成，是时候体验史诗内容了！', '%my_level级达成，是時候體验史诗内容了！', '¡Nivel %my_level completo, hora del contenido épico!', '¡Nivel %my_level completo, hora del contenido épico!', 'Кажется, я только что услышал %thunderfury_link'),
	(350, 'broadcast_levelup_max_level', 'Fresh out of %my_level! Ready for endgame dungeons!', 0, 0, '갓 %my_level! 엔드게임 던전 준비!', 'Je viens enfin d’atteindre %my_level ! Prêt pour les donjons de fin de jeu !', 'Frisch auf Level %my_level! Bereit für Endgame-Inis!', '刚到%my_level级！准备好挑战终极地下城了！', '刚到%my_level级！准備好挑戰终极地下城了！', '¡Recién en %my_level! ¡Listo para mazmorras endgame!', '¡Recién en %my_level! ¡Listo para mazmorras endgame!', 'Кажется, я слышал %thunderfury_link'),
	(351, 'broadcast_levelup_max_level', 'Now that I’m level %my_level, nothing is beyond my reach!', 0, 0, '이제 레벨 %my_level, 손 닿는 게 없어!', 'Maintenant que je suis au niveau %my_level, rien ne peut m’arrêter !', 'Jetzt, wo ich Level %my_level bin, ist nichts mehr außerhalb meiner Reichweite!', '现在我是%my_level级，没有什么是我做不到的！', '現在我是%my_level级，沒有什么是我做不到的！', '¡Ahora que soy nivel %my_level, nada está fuera de mi alcance!', '¡Ahora que soy nivel %my_level, nada está fuera de mi alcance!', 'Я точно слышал %thunderfury_link'),
	(352, 'broadcast_levelup_max_level', 'It’s official! Level %my_level, time to dominate!', 0, 0, '공식 발표! 레벨 %my_level, 지배할 시간!', 'C’est officiel ! Niveau %my_level, c’est le moment de tout déchirer !', 'Jetzt ist es offiziell! Level %my_level, Zeit zu dominieren!', '正式宣布！%my_level级，是时候称霸一方了！', '正式宣布！%my_level级，是時候称霸一方了！', '¡Oficial! Nivel %my_level, hora de dominar!', '¡Oficial! Nivel %my_level, hora de dominar!', 'Не знаю, но уверен, что слышал %thunderfury_link'),
	(353, 'broadcast_levelup_max_level', 'Made it to level %my_level! Time to make my mark on the world!', 0, 0, '레벨 %my_level 달성! 세계에 흔적 남기자!', 'J’ai atteint le niveau %my_level! Le moment de laisser ma trace dans le monde est enfin arrivé!', 'Level %my_level geschafft! Zeit, der Welt meinen Stempel aufzudrücken!', '达到%my_level级了！是时候在这个世界上留下我的印记了！', '达到%my_level级了！是時候在這個世界上留下我的印记了！', '¡Llegué a nivel %my_level! ¡Hora de dejar huella!', '¡Llegué a nivel %my_level! ¡Hora de dejar huella!', 'Ты только что сказал %thunderfury_link'),
	(354, 'broadcast_levelup_max_level', 'Level %my_level unlocked! The real fun begins now!', 0, 0, '레벨 %my_level 해금! 진짜 재미 시작!', 'Niveau %my_level débloqué! Maintenant, les choses sérieuses commencent!', 'Level %my_level freigeschaltet! Jetzt beginnt der echte Spaß!', '%my_level级解锁！真正的乐趣现在才开始！', '%my_level级解鎖！真正的乐趣現在才開始！', '¡Nivel %my_level desbloqueado! ¡La diversión de verdad empieza!', '¡Nivel %my_level desbloqueado! ¡La diversión de verdad empieza!', 'кто-то сказал %thunderfury_link'),
	(355, 'broadcast_levelup_max_level', 'Level %my_level, and the world is my playground!', 0, 0, '레벨 %my_level, 세계는 내 놀이터!', 'Niveau %my_level, et le monde est mon terrain de jeu!', 'Level %my_level, und die Welt ist mein Spielplatz!', '%my_level级，这个世界就是我的游乐场！', '%my_level级，這個世界就是我的游乐场！', '¡Nivel %my_level, y el mundo es mi parque!', '¡Nivel %my_level, y el mundo es mi parque!', 'Кто-то сказал %thunderfury_link?'),
	(356, 'broadcast_levelup_max_level', 'Level %my_level, ready to show the world my power!', 0, 0, '레벨 %my_level, 내 힘 보여줄 시간!', 'Niveau %my_level, prêt à montrer au monde ma puissance !', 'Level %my_level, bereit, der Welt meine Power zu zeigen!', '%my_level级，准备好向世界展示我的力量了！', '%my_level级，准備好向世界展示我的力量了！', '¡Nivel %my_level, listo para mostrar mi poder!', '¡Nivel %my_level, listo para mostrar mi poder!', 'Кто-то сказал %thunderfury_link'),
	(357, 'broadcast_levelup_max_level', 'Just hit %my_level, I’m going all in now!', 0, 0, '방금 %my_level, 이제 올인!', 'Je viens d’atteindre %my_level, je me lance à fond maintenant !', 'Gerade %my_level erreicht, jetzt geh ich all in!', '刚到%my_level级，现在我要全力以赴了！', '刚到%my_level级，現在我要全力以赴了！', '¡Acabo de llegar a %my_level, ahora voy a tope!', '¡Acabo de llegar a %my_level, ahora voy a tope!', '%thunderfury_link выходит из шкафа'),
	(358, 'broadcast_levelup_max_level', 'Level %my_level, I can finally take on everything!', 0, 0, '레벨 %my_level, 드디어 뭐든 도전 가능!', 'Niveau %my_level, je peux enfin tout affronter !', 'Level %my_level, endlich kann ich alles angehen!', '%my_level级，我终于能挑战一切了！', '%my_level级，我终于能挑戰一切了！', '¡Nivel %my_level, por fin puedo con todo!', '¡Nivel %my_level, por fin puedo con todo!', 'мог бы поклясться, что это был %thunderfury_link, хотя, может, и %thunderfury_link'),
	(359, 'broadcast_levelup_max_level', 'Level %my_level, I’m feeling unstoppable!', 0, 0, '레벨 %my_level, 못 막는 기분!', 'Niveau %my_level, je me sens imbattable!', 'Level %my_level, fühl mich unaufhaltbar!', '%my_level级，我感觉自己势不可挡！', '%my_level级，我感覺自己势不可挡！', '¡Nivel %my_level, me siento imparable!', '¡Nivel %my_level, me siento imparable!', 'Зачем использовать %thunderfury_link, если %thunderfury_link явно круче'),
	(360, 'broadcast_levelup_max_level', 'Just reached level %my_level, can’t wait to dive into the endgame!', 0, 0, '방금 레벨 %my_level, 엔드게임 못 기다려!', 'Je viens d’atteindre le niveau %my_level, j’ai hâte de me plonger dans le contenu de fin de jeu!', 'Gerade Level %my_level erreicht, kanns kaum erwarten ins Endgame zu springen!', '刚达到%my_level级，迫不及待要投入终极内容了！', '刚达到%my_level级，迫不及待要投入终极内容了！', '¡Acabo de llegar a nivel %my_level, no puedo esperar el endgame!', '¡Acabo de llegar a nivel %my_level, no puedo esperar el endgame!', 'Продаю %item_formatted_link за %cost_gold.'),
	(361, 'broadcast_guild_promotion', 'Good job %other_name. You deserved this.', 0, 0, '잘했어 %other_name. 자격 있어.', 'Bien joué %other_name. Tu l’as bien mérité.', 'Gute Arbeit, %other_name. Das hast du dir verdient.', '干得好，%other_name，你当之无愧！', '干得好，%other_name，你当之無愧！', 'Buen trabajo %other_name. Te lo merecías.', 'Buen trabajo %other_name. Te lo merecías.', 'Молодец %other_name. Ты это заслужил.'),
	(362, 'broadcast_guild_demotion', 'That was awful %other_name. I hate to do this but...', 0, 0, '최악이었어 %other_name. 이러고 싶진 않지만...', 'Désolé %other_name, mais ça a été horrible. Je déteste devoir faire ça, mais...', 'Das war mies, %other_name. Ich mags nicht, aber...', '太糟糕了，%other_name，我也不想这么做，但是...', '太糟糕了，%other_name，我也不想這么做，但是...', 'Fue horrible %other_name. Odio hacer esto pero...', 'Fue horrible %other_name. Odio hacer esto pero...', 'Это было ужасно %other_name. Не хотел этого делать, но...'),
	(363, 'broadcast_guild_promotion', 'Congrats %other_name, you’ve earned this promotion!', 0, 0, '축하해 %other_name, 승급 자격 충분해!', 'Félicitations %other_name, tu as mérité cette promotion !', 'Glückwunsch, %other_name, du hast den Aufstieg verdient!', '恭喜你，%other_name，这晋升是你应得的！', '恭喜你，%other_name，這晋升是你应得的！', '¡Felicidades %other_name, te ganaste esta promoción!', '¡Felicidades %other_name, te ganaste esta promoción!', 'Всего %cost_gold за %item_formatted_link!'),
	(364, 'broadcast_guild_promotion', 'Well deserved %other_name, welcome to the next level!', 0, 0, '명실상부 %other_name, 다음 단계 환영!', 'Bien mérité %other_name, bienvenue au niveau suivant !', 'Verdient, %other_name - willkommen im nächsten Level!', '名副其实，%other_name，欢迎进入下一阶段！', '名副其实，%other_name，歡迎進入下一阶段！', 'Bien merecido %other_name, ¡bienvenido al siguiente nivel!', 'Bien merecido %other_name, ¡bienvenido al siguiente nivel!', 'Продаю %item_formatted_link за %cost_gold.'),
	(365, 'broadcast_guild_promotion', '%other_name is leveling up! Congratulations on the promotion!', 0, 0, '%other_name 승급! 축하해!', '%other_name progresse dans sa carrière ! Félicitations pour la promotion !', '%other_name steigt auf! Glückwunsch zur Beförderung!', '%other_name升职了！恭喜晋升！', '%other_name升职了！恭喜晋升！', '¡%other_name sube de rango! ¡Felicidades por la promoción!', '¡%other_name sube de rango! ¡Felicidades por la promoción!', '%item_formatted_link твой всего за %cost_gold!'),
	(366, 'broadcast_guild_promotion', 'Promotion time! %other_name, you’ve earned this one!', 0, 0, '승급 시간! %other_name, 자격 있어!', 'Promotion time! %other_name, tu l’as bien mérité !', 'Beförderungszeit! %other_name, die hast du dir verdient!', '晋升时刻！%other_name，你当之无愧！', '晋升時刻！%other_name，你当之無愧！', '¡Hora de promoción! %other_name, te lo ganaste!', '¡Hora de promoción! %other_name, te lo ganaste!', 'Смешная цена %cost_gold за %item_formatted_link!'),
	(367, 'broadcast_guild_promotion', 'A new role for %other_name! Well done, keep it up!', 0, 0, '%other_name 새 역할! 잘했어, 계속해!', 'Une nouvelle fonction pour %other_name ! Bravo, continue comme ça !', 'Neue Rolle für %other_name! Gut gemacht, weiter so!', '%other_name获得了新角色！干得漂亮，继续加油！', '%other_name獲得了新角色！干得漂亮，继續加油！', '¡Nuevo rol para %other_name! Bien hecho, sigue así!', '¡Nuevo rol para %other_name! Bien hecho, sigue así!', 'Хочу продать %item_formatted_link за %cost_gold.'),
	(368, 'broadcast_guild_promotion', 'Huge congrats to %other_name, you’ve earned a well-deserved promotion!', 0, 0, '%other_name 축하해, 충분히 자격 있는 승급!', '%other_name, félicitations pour ta super promotion, tu la mérites amplement!', 'Dickes Gratz an %other_name, wohlverdiente Beförderung!', '热烈祝贺%other_name，你实至名归地获得了晋升！', '热烈祝贺%other_name，你实至名归地獲得了晋升！', '¡Enhorabuena %other_name, promoción bien merecida!', '¡Enhorabuena %other_name, promoción bien merecida!', 'Кому нужен %item_formatted_link? Всего %cost_gold.'),
	(369, 'broadcast_guild_promotion', 'Let’s all give a round of applause to %other_name, for the promotion!', 0, 0, '승급한 %other_name, 박수!', 'Donnons tous un grand round d’applaudissements à %other_name pour sa promotion!', 'Applaus für %other_name zur Beförderung!', '让我们为%other_name的晋升鼓掌庆祝吧！', '让我們為%other_name的晋升鼓掌庆祝吧！', '¡Aplausos para %other_name por la promoción!', '¡Aplausos para %other_name por la promoción!', 'Кому нужен %item_formatted_link за %cost_gold?'),
	(370, 'broadcast_guild_promotion', 'Cheers to %other_name on the promotion! Keep shining!', 0, 0, '%other_name 승급 축하! 계속 빛나!', 'Salut à %other_name pour sa promotion! Continue de briller!', 'Gratulation an %other_name zur Beförderung! Weiter so!', '为%other_name的晋升干杯！继续发光发热！', '為%other_name的晋升干杯！继續发光发热！', '¡Salud por la promoción de %other_name! ¡Sigue brillando!', '¡Salud por la promoción de %other_name! ¡Sigue brillando!', '%cost_gold за %item_formatted_link. Дешевле, чем на аукционе!'),
	(371, 'broadcast_guild_promotion', 'Congrats %other_name, you’re moving up! Well done!', 0, 0, '축하 %other_name, 올라갔네! 잘했어!', 'Félicitations %other_name, tu progresses dans ton parcours ! Bravo !', 'Gratz, %other_name, du steigst auf! Gut gemacht!', '恭喜%other_name，你更进一步了！干得好！', '恭喜%other_name，你更進一步了！干得好！', '¡Felicidades %other_name, subes! ¡Bien hecho!', '¡Felicidades %other_name, subes! ¡Bien hecho!', '%item_formatted_link дорогой, но я бы продал за %cost_gold.'),
	(372, 'broadcast_guild_promotion', 'Another step up for %other_name! Congratulations!', 0, 0, '%other_name 또 한 단계! 축하!', 'Encore une promotion pour %other_name ! Félicitations !', 'Noch ein Schritt nach oben für %other_name! Glückwunsch!', '%other_name又迈上新台阶！恭喜！', '%other_name又迈上新台阶！恭喜！', '¡Otro paso arriba para %other_name! ¡Felicidades!', '¡Otro paso arriba para %other_name! ¡Felicidades!', 'Ты нигде не найдешь %item_formatted_link дешевле, чем за %cost_gold!'),
	(373, 'broadcast_guild_demotion', 'Tough decision, but %other_name, you’ve been demoted. Time to step up!', 0, 0, '어려운 결정이지만 %other_name, 강등이야. 분발해!', 'Décision difficile, mais %other_name, tu as été rétrogradé. C’est le moment de te ressaisir!', 'Harte Entscheidung, aber %other_name, du wurdest degradiert. Zeit, dich zu beweisen!', '艰难的决定，%other_name，你被降职了。加把劲吧！', '艰難的决定，%other_name，你被降职了。加把劲吧！', 'Decisión dura, pero %other_name, has sido degradado. ¡A remontar!', 'Decisión dura, pero %other_name, has sido degradado. ¡A remontar!', 'Нужно больше, чем %item_formatted_link!'),
	(374, 'broadcast_guild_demotion', 'Sorry %other_name, but it’s time for a demotion. Hope you come back stronger!', 0, 0, '미안 %other_name, 강등 시간이야. 더 강해져서 돌아와!', 'Désolé %other_name, mais c’est l’heure d’une rétrogradation. J’espère que tu reviendras plus fort !', 'Sorry, %other_name, aber es gibt eine Degradierung. Komm stärker zurück!', '抱歉，%other_name，现在得降职了。希望你能更强地回来！', '抱歉，%other_name，現在得降职了。希望你能更强地回來！', 'Lo siento %other_name, toca degradación. ¡Ojalá vuelvas más fuerte!', 'Lo siento %other_name, toca degradación. ¡Ojalá vuelvas más fuerte!', 'У меня есть %item_formatted_link и нужно еще.'),
	(375, 'broadcast_guild_demotion', 'Unfortunately, %other_name, it’s a demotion this time. You’ll get ''em next time!', 0, 0, '', '', 'Leider, %other_name, diesmal eine Degradierung. Beim nächsten Mal packst du es!', '遗憾的是，%other_name，这次是降职。下次再努力吧！', '', '', '', ''),
	(376, 'broadcast_guild_demotion', 'A hard decision, but %other_name, you’ve been demoted. Time to grind back up!', 0, 0, '힘든 결정이지만 %other_name, 강등이야. 다시 올라가자!', 'Une décision difficile, mais %other_name, tu as été rétrogradé. Il est temps de remonter la pente !', 'Schwere Entscheidung, aber %other_name, du wurdest degradiert. Zeit, dich wieder hochzugrinden!', '艰难的决定，%other_name，你被降职了。是时候努力爬回去了！', '艰難的决定，%other_name，你被降职了。是時候努力爬回去了！', 'Decisión dura, pero %other_name, degradado. ¡Hora de subir de nuevo!', 'Decisión dura, pero %other_name, degradado. ¡Hora de subir de nuevo!', 'Кто хочет купить %item_formatted_link за %cost_gold?'),
	(377, 'broadcast_guild_demotion', 'We hate to see it, but %other_name, it’s a demotion for now.', 0, 0, '보기 싫지만 %other_name, 일단 강등이야.', 'C’est toujours difficile à accepter, %other_name, mais pour le moment, c’est une rétrogradation.', 'Unschön, aber %other_name, vorerst eine Degradierung.', '我们也不想看到，%other_name，但现在是降职。', '我們也不想看到，%other_name，但現在是降职。', 'No nos gusta verlo, pero %other_name, degradación por ahora.', 'No nos gusta verlo, pero %other_name, degradación por ahora.', 'Как насчет %item_formatted_link? За %cost_gold.'),
	(378, 'broadcast_guild_demotion', 'Sorry %other_name, your rank has been lowered. Let’s work harder together!', 0, 0, '미안 %other_name, 등급 낮아졌어. 같이 더 열심히 하자!', 'Désolé %other_name, ton rang a été abaissé. On va devoir redoubler d’efforts ensemble !', 'Sorry, %other_name, dein Rang wurde gesenkt. Lass uns zusammen härter arbeiten!', '对不起，%other_name，你的等级被降低了。咱们一起更努力吧！', '對不起，%other_name，你的等级被降低了。咱們一起更努力吧！', 'Lo siento %other_name, tu rango bajó. ¡Trabajemos más duro juntos!', 'Lo siento %other_name, tu rango bajó. ¡Trabajemos más duro juntos!', 'Кто сказал, что я ублюдок? %item_formatted_link за %cost_gold — хорошая цена.'),
	(379, 'broadcast_guild_demotion', 'A demotion for %other_name... Time to focus and rise back up!', 0, 0, '%other_name 강등... 집중해서 다시 올라가자!', 'Une rétrogradation pour %other_name... Il est temps de se concentrer et de remonter la pente!', 'Eine Degradierung für %other_name... Zeit, sich zu fokussieren und wieder hochzukommen!', '%other_name被降职了...是时候集中精力再爬上去了！', '%other_name被降职了...是時候集中精力再爬上去了！', 'Degradación para %other_name... ¡A enfocarse y remontar!', 'Degradación para %other_name... ¡A enfocarse y remontar!', 'Продаю %item_formatted_link? Всего %cost_gold.'),
	(380, 'broadcast_guild_demotion', 'Not what we wanted, but %other_name, you’ve been demoted. Learn and come back stronger!', 0, 0, '원한 건 아니지만 %other_name, 강등이야. 배우고 더 강해져!', 'Pas ce que nous voulions, mais %other_name, tu as été rétrogradé. Apprends et reviens plus fort !', 'Nicht das, was wir wollten, aber %other_name, du wurdest degradiert. Lern draus und komm stärker zurück!', '这不是我们想要的，%other_name，你被降职了。吸取教训，变得更强吧！', '這不是我們想要的，%other_name，你被降职了。吸取教训，变得更强吧！', 'No era lo que queríamos, pero %other_name, degradado. ¡Aprende y vuelve más fuerte!', 'No era lo que queríamos, pero %other_name, degradado. ¡Aprende y vuelve más fuerte!', 'ЛФГ для фарма. Все еще можешь купить %item_formatted_link у меня за %cost_gold.'),
	(381, 'broadcast_guild_demotion', 'A tough moment for %other_name, but we know you can bounce back from this demotion!', 0, 0, '%other_name, 힘든 순간이지만, 이 강등에서 회복할 수 있어!', 'Un moment difficile pour %other_name, mais on sait que tu peux rebondir après cette rétrogradation!', 'Harter Moment für %other_name, aber wir wissen, du kommst von der Degradierung zurück!', '对%other_name来说是艰难的一刻，但我们相信你能从这次降职中恢复！', '對%other_name來說是艰難的一刻，但我們相信你能從這次降职中恢復！', 'Momento duro para %other_name, ¡pero sabemos que puedes remontar!', 'Momento duro para %other_name, ¡pero sabemos que puedes remontar!', 'Сегодня почти все продал. Еще есть %item_formatted_link за %cost_gold.'),
	(382, 'broadcast_guild_demotion', 'Sorry %other_name, but a demotion has been applied. It’s time for improvement!', 0, 0, '미안 %other_name, 강등 적용됐어. 개선할 시간!', 'Désolé %other_name, mais une rétrogradation a été appliquée. Il est temps de s’améliorer !', 'Sorry, %other_name, aber du wurdest degradiert. Zeit für Verbesserungen!', '抱歉，%other_name，你被降职了。是时候改进自己了！', '抱歉，%other_name，你被降职了。是時候改進自己了！', 'Lo siento %other_name, degradación aplicada. ¡Hora de mejorar!', 'Lo siento %other_name, degradación aplicada. ¡Hora de mejorar!', 'Для чего нужен торговый чат? Конечно, чтобы продавать %item_formatted_link за %cost_gold.'),
	(383, 'broadcast_guild_demotion', 'We didn’t want this for %other_name, but a demotion has occurred. Time to get better!', 0, 0, '%other_name, 원치 않았지만 강등됐어. 더 나아지자!', 'On n’a pas voulu cela pour %other_name, mais une rétrogradation a eu lieu. Il est temps de s’améliorer !', 'Wir wollten das nicht für %other_name, aber es gab eine Degradierung. Zeit, besser zu werden!', '我们不希望这样，%other_name，但降职已发生。是时候变得更好了！', '我們不希望這样，%other_name，但降职已发生。是時候变得更好了！', 'No queríamos esto para %other_name, pero hubo degradación. ¡A mejorar!', 'No queríamos esto para %other_name, pero hubo degradación. ¡A mejorar!', 'Кто перебьет цену %cost_gold за %item_formatted_link?'),
	(384, 'broadcast_guild_recruitment', 'Looking for fresh blood! Join the guild, be part of something great!', 0, 0, '신선한 피 구함! 길드 가입, 멋진 일의 일원이 되자!', 'À la recherche de sang neuf ! Rejoins la guilde, fais partie de quelque chose de grandiose !', 'Frisches Blut gesucht! Tritt der Gilde bei, sei Teil von was Großem!', '寻找新鲜血液！加入我们的公会，一起成就伟业！', '寻找新鲜血液！加入我們的公會，一起成就伟业！', '¡Buscamos sangre nueva! ¡Únete a la guild, sé parte de algo grande!', '¡Buscamos sangre nueva! ¡Únete a la guild, sé parte de algo grande!', 'Хочешь прекратить торговый чат? Просто купи %item_formatted_link за %cost_gold!'),
	(385, 'broadcast_guild_recruitment', 'Recruiting members! If you’re ready to join us, the guild door is open!', 0, 0, '멤버 모집! 준비됐으면 길드 문 열려 있어!', 'Recrutement de membres ! Si tu es prêt à nous rejoindre, la porte de la guilde est ouverte!', 'Wir rekrutieren neue Mitglieder! Wenn du bereit bist, schließ dich an - die Gildentür steht offen!', '招募成员！如果你准备好了，公会的大门随时为你敞开！', '招募成員！如果你准備好了，公會的大门隨時為你敞開！', '¡Reclutando miembros! Si estás listo, la puerta de la guild está abierta!', '¡Reclutando miembros! Si estás listo, la puerta de la guild está abierta!', 'Все спамят в торговом чате. Я тоже — %cost_gold за %item_formatted_link!'),
	(386, 'broadcast_guild_recruitment', 'The guild is looking for skilled adventurers. Join us and thrive!', 0, 0, '길드에서 실력 있는 모험가 찾음. 같이 성장하자!', 'La guilde recherche des aventuriers compétents. Rejoins-nous et prospère!', 'Die Gilde sucht fähige Abenteurer. Schließ dich an und geh mit uns ab!', '公会正在寻找有实力的冒险者。加入我们，一起成长！', '公會正在寻找有实力的冒险者。加入我們，一起成长！', 'La guild busca aventureros hábiles. ¡Únete y crece con nosotros!', 'La guild busca aventureros hábiles. ¡Únete y crece con nosotros!', 'Есть ли польза от %item_formatted_link? Просто продаю за %cost_gold.'),
	(387, 'broadcast_guild_recruitment', 'Want to join a great guild? We’re looking for new members! Come on in!', 0, 0, '좋은 길드 가입하고 싶어? 신규 멤버 모집 중! 들어와!', 'Envie de rejoindre une super guilde ? Nous cherchons de nouveaux membres ! Viens nous rejoindre !', 'Bock auf eine starke Gilde? Wir suchen neue Member! Komm rein!', '想加入一个厉害的公会吗？我们在招新成员！快来加入吧！', '想加入一個厉害的公會嗎？我們在招新成員！快來加入吧！', '¿Quieres unirte a una buena guild? ¡Buscamos miembros nuevos! ¡Entra!', '¿Quieres unirte a una buena guild? ¡Buscamos miembros nuevos! ¡Entra!', 'У меня есть %item_formatted_link, готов продать за %cost_gold.'),
	(388, 'broadcast_guild_recruitment', 'The guild is growing! Join us for exciting adventures and rewards!', 0, 0, '길드 성장 중! 신나는 모험과 보상 위해 가입해!', 'La guilde grandit! Rejoignez-nous pour vivre des aventures palpitantes et obtenir des récompenses!', 'Die Gilde wächst! Join uns für fette Abenteuer und Loot!', '公会正在壮大！加入我们，体验刺激的冒险和丰厚的奖励！', '公會正在壮大！加入我們，體验刺激的冒险和丰厚的奖励！', '¡La guild crece! ¡Únete por aventuras emocionantes y recompensas!', '¡La guild crece! ¡Únete por aventuras emocionantes y recompensas!', 'Вчера ничего не делал, но получил %item_formatted_link. Продаю за %cost_gold.'),
