	(990, 'thunderfury_spam', 'Why use %thunderfury_link when %thunderfury_link is clearly way more OP', 0, 0, '%thunderfury_link 쓸 바엔 %thunderfury_link 가 훨씬 OP인데', 'Pourquoi utiliser %thunderfury_link quand %thunderfury_link est clairement beaucoup plus puissant.', 'warum %thunderfury_link nutzen, wenn %thunderfury_link offensichtlich viel stärker ist', '为什么用%thunderfury_link，%thunderfury_link明显更强啊！', '為什么用%thunderfury_link，%thunderfury_link明显更强啊！', '¿Para qué usar %thunderfury_link si %thunderfury_link es claramente más OP?', '¿Para qué usar %thunderfury_link si %thunderfury_link es claramente más OP?', 'Зачем использовать %thunderfury_link, если %thunderfury_link явно круче'),
	(991, 'thunderfury_spam', 'Did I just hear %thunderfury_link?', 0, 0, '방금 %thunderfury_link 들었어?', 'Ai-je juste entendu %thunderfury_link?', 'hab ich gerade %thunderfury_link gehört?', '我刚才是听到%thunderfury_link了吗？', '我刚才是听到%thunderfury_link了嗎？', '¿Acabo de oír %thunderfury_link?', '¿Acabo de oír %thunderfury_link?', 'Я только что услышал %thunderfury_link?'),
	(992, 'thunderfury_spam', 'No way... is that a %thunderfury_link I hear?', 0, 0, '설마... %thunderfury_link 소리야?', 'Pas possible... Est-ce que j’entends %thunderfury_link ?', 'niemals... hör ich da echt %thunderfury_link?', '不会吧……我听到了%thunderfury_link？', '不會吧……我听到了%thunderfury_link？', 'No puede ser... ¿oigo un %thunderfury_link?', 'No puede ser... ¿oigo un %thunderfury_link?', 'Не может быть... это %thunderfury_link я слышу?'),
	(993, 'thunderfury_spam', '%thunderfury_link? Sounds like something only legends wield!', 0, 0, '%thunderfury_link? 전설만 들 수 있는 거 아냐?', '%thunderfury_link? Ça a l’air d’être quelque chose que seuls les légendes manient!', '%thunderfury_link? klingt nach was, das nur Legenden führen!', '%thunderfury_link？听起来只有传说中的英雄才能驾驭！', '%thunderfury_link？听起來只有傳說中的英雄才能驾驭！', '¿%thunderfury_link? Suena a algo que solo empuñan leyendas!', '¿%thunderfury_link? Suena a algo que solo empuñan leyendas!', '%thunderfury_link? Звучит как оружие легенд!'),
