	(1464, 'taunt', 'Fie! Drop thee into the rotten mouth of Death!', 0, 0, '쯧! 썩은 죽음의 입에 떨어져라!', 'Que le diable t’emporte dans la gueule pourrie de la Mort!', 'Wenn Unfähigkeit ’ne Klasse wäre, hättest du sie gemaxt.', '呸！掉进死亡的腐烂大嘴去吧！', '呸！掉進死亡的腐烂大嘴去吧！', '¡Fie! ¡Déjate caer en la podrida boca de la Muerte!', '¡Fie! ¡Déjate caer en la podrida boca de la Muerte!', 'Фу! Брось себя в гнилую пасть Смерти!'),
	(1465, 'taunt', '<target>, you are a fishmonger!', 0, 0, '<target>, 너 생선 장수야!', '<target>, tu es poissonnier!', '<target> du dummes Arschfurz-Teppichladen-Arschloch', '<target>，你就是个卖鱼的！', '<target>，你就是個賣鱼的！', '<target>, ¡eres un pescadero!', '<target>, ¡eres un pescadero!', '<target>, ты торговец рыбой!'),
