	(1694, 'bis_applied_msg', 'BiS applied', 0, 0, 'BiS 장비가 적용되었습니다.', 'Équipement BiS appliqué.', 'BiS-Ausrüstung angewendet.', 'BiS装备已应用。', 'BiS裝備已套用。', 'Equipo BiS aplicado.', 'Equipo BiS aplicado.', 'BiS-снаряжение применено.'),
	(1695, 'bis_applying_msg', 'Applying BiS gear', 0, 0, 'BiS 장비를 적용합니다.', 'Application de l''équipement BiS.', 'Wende BiS-Ausrüstung an.', '正在装备BiS装备。', '正在裝備BiS裝備。', 'Aplicando equipo BiS.', 'Aplicando equipo BiS.', 'Применяю BiS-снаряжение.'),
	(1696, 'bis_arg_above_limit_error', 'BiS ilvl %requested exceeds AutoGearScoreLimit %limit, refusing', 0, 0, 'BiS 아이템 레벨 %requested이(가) AutoGearScoreLimit %limit을(를) 초과합니다. 거부합니다.', 'iLvl BiS %requested dépasse AutoGearScoreLimit %limit, refusé.', 'BiS-iLvl %requested überschreitet AutoGearScoreLimit %limit, abgelehnt.', 'BiS物品等级%requested超过AutoGearScoreLimit %limit，已拒绝。', 'BiS物品等級%requested超過AutoGearScoreLimit %limit，已拒絕。', 'iLvl BiS %requested supera AutoGearScoreLimit %limit, rechazado.', 'iLvl BiS %requested supera AutoGearScoreLimit %limit, rechazado.', 'BiS iLvl %requested превышает AutoGearScoreLimit %limit, отказано.'),
	(1697, 'bis_autogear_unavailable_error', 'autogear command is not allowed, please check the configuration.', 0, 0, '자동 장비 명령이 허용되지 않습니다. 설정을 확인하세요.', 'La commande autogear n''est pas autorisée, veuillez vérifier la configuration.', 'Der autogear-Befehl ist nicht erlaubt, bitte überprüfe die Konfiguration.', '自动装备命令未启用，请检查配置。', '自動裝備指令未啟用，請檢查設定。', 'El comando autogear no está permitido, por favor revisa la configuración.', 'El comando autogear no está permitido, por favor revisa la configuración.', 'Команда autogear не разрешена, проверьте конфигурацию.'),
	(1698, 'bis_closest_match_msg', 'No BiS at ilvl %requested, using closest match at ilvl %resolved', 0, 0, '아이템 레벨 %requested의 BiS가 없어 가장 가까운 아이템 레벨 %resolved을(를) 사용합니다.', 'Pas de BiS à l''iLvl %requested, utilisation de la correspondance la plus proche à l''iLvl %resolved.', 'Kein BiS auf iLvl %requested, verwende nächstliegende Übereinstimmung auf iLvl %resolved.', '物品等级%requested没有BiS，使用最接近的物品等级%resolved。', '物品等級%requested沒有BiS，使用最接近的物品等級%resolved。', 'No hay BiS en iLvl %requested, usando coincidencia más cercana en iLvl %resolved.', 'No hay BiS en iLvl %requested, usando coincidencia más cercana en iLvl %resolved.', 'Нет BiS на iLvl %requested, использую ближайшее совпадение на iLvl %resolved.'),
	(1699, 'bis_command_unavailable_error', 'bis command is not allowed, please check the configuration.', 0, 0, 'bis 명령이 허용되지 않습니다. 설정을 확인하세요.', 'La commande bis n''est pas autorisée, veuillez vérifier la configuration.', 'Der bis-Befehl ist nicht erlaubt, bitte überprüfe die Konfiguration.', 'bis命令未启用，请检查配置。', 'bis指令未啟用，請檢查設定。', 'El comando bis no está permitido, por favor revisa la configuración.', 'El comando bis no está permitido, por favor revisa la configuración.', 'Команда bis не разрешена, проверьте конфигурацию.'),
	(1700, 'bis_invalid_arg_error', 'Invalid BiS ilvl argument ''%param''. Use a positive integer.', 0, 0, '잘못된 BiS 아이템 레벨 인수 ''%param''. 양의 정수를 사용하세요.', 'Argument iLvl BiS invalide ''%param''. Utilisez un entier positif.', 'Ungültiges BiS-iLvl-Argument ''%param''. Verwende eine positive ganze Zahl.', '无效的BiS物品等级参数“%param”。请使用正整数。', '無效的BiS物品等級參數「%param」。請使用正整數。', 'Argumento iLvl BiS inválido ''%param''. Usa un entero positivo.', 'Argumento iLvl BiS inválido ''%param''. Usa un entero positivo.', 'Неверный аргумент iLvl BiS ''%param''. Используйте положительное целое число.'),
	(1701, 'bis_no_rows_autogear_msg', 'No BiS at ilvl %ilvl, using Autogear %ilvl instead', 0, 0, '아이템 레벨 %ilvl의 BiS가 없어 대신 Autogear %ilvl을(를) 사용합니다.', 'Pas de BiS à l''iLvl %ilvl, utilisation d''Autogear %ilvl à la place.', 'Kein BiS auf iLvl %ilvl, verwende stattdessen Autogear %ilvl.', '物品等级%ilvl没有BiS，改用Autogear %ilvl。', '物品等級%ilvl沒有BiS，改用Autogear %ilvl。', 'No hay BiS en iLvl %ilvl, usando Autogear %ilvl en su lugar.', 'No hay BiS en iLvl %ilvl, usando Autogear %ilvl en su lugar.', 'Нет BiS на iLvl %ilvl, использую Autogear %ilvl.'),
	(1702, 'bis_no_rows_fallback', 'No BiS for your tier/spec/level, check cfg, running autogear instead', 0, 0, '해당 등급/전문화/레벨에 BiS 목록이 없습니다. 설정을 확인하세요. 대신 자동 장비를 실행합니다.', 'Pas de BiS pour votre tier/spé/niveau, vérifiez la config, exécution d''autogear à la place.', 'Kein BiS für deinen Tier/Spec/Level, prüfe die Config, führe stattdessen autogear aus.', '您的等级/天赋/级别没有BiS数据，请检查配置，改为运行autogear。', '你的等級/天賦/級別沒有BiS資料，請檢查設定，改為執行autogear。', 'No hay BiS para tu tier/spec/nivel, revisa la configuración, ejecutando autogear en su lugar.', 'No hay BiS para tu tier/spec/nivel, revisa la configuración, ejecutando autogear en su lugar.', 'Нет BiS для вашего тира/спека/уровня, проверьте конфиг, запускаю autogear.'),
	(1703, 'bis_pvp_refused_error', 'bis is PvE only, bot is configured as PvP.', 0, 0, 'bis는 PvE 전용이며, 이 봇은 PvP로 설정되어 있습니다.', 'bis est uniquement pour le JcE, ce bot est configuré en JcJ.', 'bis ist nur für PvE, dieser Bot ist als PvP konfiguriert.', 'bis仅适用于PvE，此机器人配置为PvP。', 'bis僅適用於PvE，此機器人設定為PvP。', 'bis es solo para PvE, el bot está configurado como PvP.', 'bis es solo para PvE, el bot está configurado como PvP.', 'bis только для PvE, бот настроен на PvP.'),
	(1704, 'bis_quality_floor_error', 'AutoGearQualityLimit must be 4 for BiS.', 0, 0, 'BiS를 사용하려면 AutoGearQualityLimit이 4여야 합니다.', 'AutoGearQualityLimit doit être à 4 pour utiliser BiS.', 'AutoGearQualityLimit muss für BiS auf 4 stehen.', 'BiS要求AutoGearQualityLimit设置为4。', 'BiS要求AutoGearQualityLimit設定為4。', 'AutoGearQualityLimit debe ser 4 para BiS.', 'AutoGearQualityLimit debe ser 4 para BiS.', 'AutoGearQualityLimit должен быть 4 для BiS.'),
	(1705, 'bot_not_your_master', 'You are not my master!', 0, 0, '당신은 내 주인이 아닙니다!', 'Tu n''es pas mon maître !', 'Du bist nicht mein Meister!', '你不是我的主人！', '你不是我的主人！', '¡No eres mi amo!', '¡No eres mi amo!', 'Ты не мой хозяин!'),
	(1706, 'bot_rndbot_no_logout', 'You can''t command me to logout!', 0, 0, '당신은 나에게 로그아웃을 명령할 수 없습니다!', 'Tu ne peux pas m''ordonner de me déconnecter !', 'Du kannst mir nicht befehlen, mich auszuloggen!', '你不能命令我下线！', '你不能命令我登出！', '¡No puedes ordenarme que cierre sesión!', '¡No puedes ordenarme que cierre sesión!', 'Ты не можешь приказать мне выйти из игры!'),
	(1707, 'cast_self', 'self', 0, 0, '자신', 'soi-même', 'selbst', '自己', '自己', 'uno mismo', 'uno mismo', 'себя'),
	(1708, 'cast_trade_item', 'trade item', 0, 0, '거래 아이템', 'objet d''échange', 'Handelsgegenstand', '交易物品', '交易物品', 'objeto de intercambio', 'objeto de intercambio', 'предмет обмена'),
	(1709, 'clean_quest_log_started', 'Clean Quest Log command received, removing grey/trivial quests...', 0, 0, '퀘스트 로그 정리 명령을 받았습니다. 회색/사소한 퀘스트를 제거하는 중입니다...', 'Commande de nettoyage du journal des quêtes reçue, suppression des quêtes grises/triviales...', 'Befehl zum Bereinigen des Questlogs erhalten, graue/triviale Quests werden entfernt...', '已收到清理任务日志命令，正在移除灰色/琐碎任务...', '已收到清理任務日誌命令，正在移除灰色/瑣碎任務...', 'Comando para limpiar el registro de misiones recibido, eliminando misiones grises/triviales...', 'Comando para limpiar el registro de misiones recibido, eliminando misiones grises/triviales...', 'Получена команда очистки журнала заданий, удаляю серые/простые задания...'),
	(1710, 'craft_cannot_craft', 'I cannot craft this', 0, 0, '이것은 제작할 수 없습니다', 'Je ne peux pas fabriquer ceci', 'Ich kann das nicht herstellen', '我无法制作这个', '我無法製作這個', 'No puedo fabricar esto', 'No puedo fabricar esto', 'Я не могу это создать'),
	(1711, 'craft_reset', 'I will not craft anything', 0, 0, '아무것도 제작하지 않겠습니다', 'Je ne fabriquerai rien', 'Ich werde nichts herstellen', '我不会制作任何东西', '我不會製作任何東西', 'No fabricaré nada', 'No fabricaré nada', 'Я ничего не буду создавать'),
	(1712, 'craft_summary', 'I will craft %item using reagents: %reagents (craft fee: %money)', 0, 0, '재료 %reagents을(를) 사용해 %item을(를) 제작하겠습니다 (제작 수수료: %money)', 'Je fabriquerai %item en utilisant les composants : %reagents (frais de fabrication : %money)', 'Ich werde %item mit folgenden Reagenzien herstellen: %reagents (Herstellungsgebühr: %money)', '我将使用材料 %reagents 制作 %item（制作费用：%money）', '我將使用材料 %reagents 製作 %item（製作費用：%money）', 'Fabricaré %item usando los materiales: %reagents (tarifa de fabricación: %money)', 'Fabricaré %item usando los materiales: %reagents (tarifa de fabricación: %money)', 'Я изготовлю %item, используя реагенты: %reagents (плата за изготовление: %money)'),
	(1713, 'craft_usage', 'Usage: ''craft [itemId]'' or ''craft reset''', 0, 0, '사용법: ''craft [itemId]'' 또는 ''craft reset''', 'Utilisation : ''craft [itemId]'' ou ''craft reset''', 'Verwendung: ''craft [itemId]'' oder ''craft reset''', '用法：''craft [itemId]'' 或 ''craft reset''', '用法：''craft [itemId]'' 或 ''craft reset''', 'Uso: ''craft [itemId]'' o ''craft reset''', 'Uso: ''craft [itemId]'' o ''craft reset''', 'Использование: ''craft [itemId]'' или ''craft reset'''),
	(1714, 'emote_afk_break', 'Looks like time for an AFK break..', 0, 0, '자리 비울 시간인가…', 'On dirait l''heure d''une pause AFK…', 'Sieht aus wie AFK-Pause…', '该挂会儿机了……', '該掛會兒機了……', 'Hora de un break AFK…', 'Hora de un break AFK…', 'Похоже, пора на AFK…'),
	(1715, 'emote_ass_about_it', 'Doesn''t mean you need to be an ass about it..', 0, 0, '그렇다고 그렇게 까칠할 필요는 없어…', 'Ça veut pas dire qu''il faut être con…', 'Heißt nicht, dass du ein Arsch sein musst…', '不代表你要这么混蛋。', '不代表你要這麼混蛋。', 'No significa que seas un idiota…', 'No significa que seas un idiota…', 'Не значит, что надо быть козлом…'),
	(1716, 'emote_awwwww', 'Awwwww...', 0, 0, '아……', 'Oooooh…', 'Awwwww…', '唉……', '唉……', 'Awwwww…', 'Awwwww…', 'О-o-oh…'),
	(1717, 'emote_back_of_class', 'Yes.. you.. at the back of the class..', 0, 0, '그래… 맨 뒤에 있는 너…', 'Oui… toi… au fond de la classe…', 'Ja… du… hinten in der Klasse…', '对……你……后排那位……', '對……你……後排那位……', 'Sí… tú… al fondo de la clase…', 'Sí… tú… al fondo de la clase…', 'Да… ты… с задней парты…'),
	(1718, 'emote_beg_nothing', 'Beg all you want.. I have nothing for you.', 0, 0, '아무리 빌어도 줄 게 없어.', 'Demande tant que tu veux… j''ai rien pour toi.', 'Bettel ruhig… ich hab nix für dich.', '随便求，我啥也不给。', '隨便求，我啥也不給。', 'Pide lo que quieras… no tengo nada.', 'Pide lo que quieras… no tengo nada.', 'Умоляй сколько хочешь — мне нечего.'),
	(1719, 'emote_blah_blah', 'Blah Blah Blah Yakety Smackety..', 0, 0, '블라블라블라…', 'Blah blah blah…', 'Blah Blah Blah…', '巴拉巴拉……', '巴拉巴拉……', 'Blah blah blah…', 'Blah blah blah…', 'Бла-бла-бла…'),
	(1720, 'emote_break_over', 'What? Break time''s over? Fine..', 0, 0, '뭐? 쉬는 시간 끝? 알았어…', 'Quoi ? La pause est finie ? Bon…', 'Was? Pause vorbei? Na gut…', '啥？休息结束了？行吧……', '啥？休息結束了？行吧……', '¿Qué? ¿Se acabó la pausa? Vale…', '¿Qué? ¿Se acabó la pausa? Vale…', 'Что? Перерыв кончился? Ладно…'),
	(1721, 'emote_break_time', 'Is it break time already?', 0, 0, '벌써 쉬는 시간이야?', 'C''est déjà l''heure de la pause ?', 'Schon Pause?', '已经休息时间了？', '已經休息時間了？', '¿Ya es la pausa?', '¿Ya es la pausa?', 'Уже перерыв?'),
	(1722, 'emote_can_do_too', 'What?! I can do that TOO!', 0, 0, '뭐?! 나도 할 수 있어!', 'Quoi ?! Je peux le faire AUSSI !', 'Was?! Das kann ICH auch!', '啥？！我也会！', '啥？！我也會！', '¿Qué?! ¡Yo también puedo!', '¿Qué?! ¡Yo también puedo!', 'Что?! Я тоже могу!'),
	(1723, 'emote_chicken', 'We''ll see who''s chicken soon enough!', 0, 0, '곧 누가 겁쟁이인지 보자!', 'On verra bien qui est le lâche !', 'Mal sehen, wer die Memme ist!', '看谁先怂！', '看誰先慫！', '¡Veremos quién es el gallina!', '¡Veremos quién es el gallina!', 'Скоро увидим, кто трус!'),
	(1724, 'emote_clobbering', 'It''s clobbering time!', 0, 0, '두들겨 패 줄 시간!', 'C''est l''heure de la raclée !', 'Es ist Klopp-Zeit!', '开扁时间到！', '開扁時間到！', '¡Hora de partir la cara!', '¡Hora de partir la cara!', 'Время поколотить!'),
	(1725, 'emote_deserve_that', 'What did I do to deserve that?', 0, 0, '내가 뭘 잘못했는데?', 'Qu''est-ce que j''ai fait pour mériter ça ?', 'Was hab ich getan?', '我干啥了要受这个？', '我幹啥了要受這個？', '¿Qué hice para merecer esto?', '¿Qué hice para merecer esto?', 'За что мне это?'),
	(1726, 'emote_did_i_do_that', 'Did I do thaaaaat?', 0, 0, '내가 그랬나…?', 'C''est moi qui ai fait çaaaaa ?', 'War das iiiiich?', '是我干的吗？', '是我幹的嗎？', '¿Fui yo?', '¿Fui yo?', 'Это я сделал?'),
	(1727, 'emote_do_about_that', 'And what exactly am I supposed to do about that?', 0, 0, '그럼 내가 뭘 하라고?', 'Et je suis censé faire quoi ?', 'Und was soll ich dagegen tun?', '那我到底该咋办？', '那我到底該怎麼辦？', '¿Y qué se supone que haga?', '¿Y qué se supone que haga?', 'И что я должен с этим делать?'),
	(1728, 'emote_dont_kill_me', 'Please don''t kill me!', 0, 0, '제발 살려줘!', 'Ne me tue pas !', 'Bitte töte mich nicht!', '别杀我！', '別殺我！', '¡Por favor no me mates!', '¡Por favor no me mates!', 'Пожалуйста, не убивай!'),
	(1729, 'emote_follow_you', 'Wherever you go, I''ll follow..', 0, 0, '어디든 따라갈게…', 'Où que tu ailles, je te suis…', 'Wohin du gehst, folge ich…', '你去哪儿我就跟到哪儿……', '你去哪兒我就跟到哪兒……', 'Donde vayas, te sigo…', 'Donde vayas, te sigo…', 'Куда ты — туда и я…'),
	(1730, 'emote_germs', 'Ewww! Keep your nasty germs over there!', 0, 0, '윽! 더러운 세균 멀리해!', 'Beurk ! Garde tes microbes là-bas !', 'Igitt! Halt deine Keime fern!', '噫！把你的细菌拿远点！', '噫！把你的細菌拿遠點！', '¡Puaj! ¡Guarda tus gérmenes allá!', '¡Puaj! ¡Guarda tus gérmenes allá!', 'Фу! Держи микробов подальше!'),
	(1731, 'emote_good_doggy', 'Who''s a good doggy? You''re a good doggy!', 0, 0, '착한 강아지가 누구야? 너야!', 'C''est qui le bon chien ? C''est toi !', 'Wer ist ein braves Hündchen? Du!', '谁是好狗狗？你是好狗狗！', '誰是好狗狗？你是好狗狗！', '¿Quién es un buen perrito? ¡Tú!', '¿Quién es un buen perrito? ¡Tú!', 'Кто хороший пёсик? Ты!'),
	(1732, 'emote_har_har', 'Har Har.. very funny..', 0, 0, '하하… 재밌네…', 'Ha ha… très drôle…', 'Har har… sehr witzig…', '哈呵……真搞笑……', '哈呵……真搞笑……', 'Ja ja… muy gracioso…', 'Ja ja… muy gracioso…', 'Ха-ха… очень смешно…'),
	(1733, 'emote_hercules', 'Hercules! Hercules!', 0, 0, '헤라클레스! 헤라클레스!', 'Hercule ! Hercule !', 'Hercules! Hercules!', '大力神！大力神！', '大力神！大力神！', '¡Hércules! ¡Hércules!', '¡Hércules! ¡Hércules!', 'Геркулес! Геркулес!'),
	(1734, 'emote_here_all_week', 'Thank you.. Thank you.. I''m here all week.', 0, 0, '谢谢……谢谢……我整周都在。', 'Merci… merci… je suis là toute la semaine.', 'Danke… danke… bin die ganze Woche da.', '谢谢……谢谢……我整周都在。', '謝謝……謝謝……我整周都在。', 'Gracias… gracias… toda la semana aquí.', 'Gracias… gracias… toda la semana aquí.', 'Спасибо… спасибо… я тут всю неделю.'),
	(1735, 'emote_hey_there', 'Hey there!', 0, 0, '안녕!', 'Salut !', 'Hey du!', '嘿！', '嘿！', '¡Hola!', '¡Hola!', 'Эй!'),
	(1736, 'emote_hurt_feelings', 'You hurt my feelings..', 0, 0, '상처받았어…', 'Tu m''as blessé…', 'Du verletzt meine Gefühle…', '你伤我心了……', '你傷我心了……', 'Me hieriste los sentimientos…', 'Me hieriste los sentimientos…', 'Ты задел мои чувства…'),
	(1737, 'emote_im_amazing', 'Yes, Yes. I know I''m amazing..', 0, 0, '그래 그래, 내가 대단한 거 알아…', 'Oui oui, je sais que je suis génial…', 'Ja ja, ich weiß, ich bin toll…', '是是是，我知道我很厉害。', '是是是，我知道我很厲害。', 'Sí sí, ya sé que soy increíble…', 'Sí sí, ya sé que soy increíble…', 'Да-да, знаю, я крут…'),
	(1738, 'emote_job_description', 'My job description doesn''t include entertaining you..', 0, 0, '일 설명에 널 즐겁게 하는 건 없어.', 'Mon boulot, c''est pas te divertir…', 'Unterhalten steht nicht in meiner Stellenbeschreibung…', '我的工作不包括逗你玩。', '我的工作不包括逗你玩。', 'Mi trabajo no incluye entreteneros…', 'Mi trabajo no incluye entreteneros…', 'Развлекать тебя — не в моей должностной инструкции…'),
	(1739, 'emote_just_work_here', 'Don''t look at  me.. I just work here', 0, 0, '날 보지 마… 그냥 여기서 일해', 'Me regarde pas… je travaille juste ici', 'Schau mich nicht an… arbeite nur hier', '别看我……我只是在这干活', '別看我……我只是在這幹活', 'No me mires… solo trabajo aquí', 'No me mires… solo trabajo aquí', 'Не на меня… я тут просто работаю'),
	(1740, 'emote_keep_pants', 'Keep it in your pants, boss..', 0, 0, '좀 자제해, 보스…', 'Garde ça dans ton pantalon, boss…', 'Behalt''s in der Hose, Boss…', '收敛点，老板……', '收斂點，老闆……', 'Contrólate, jefe…', 'Contrólate, jefe…', 'Сдержись, босс…'),
	(1741, 'emote_laugh_soon', 'Oh.. was I not supposed to laugh so soon?', 0, 0, '어… 너무 빨리 웃으면 안 됐나?', 'Oh… je ne devais pas rire si tôt ?', 'Oh… sollte ich noch nicht lachen?', '呃，我不该笑这么早？', '呃，我不該笑這麼早？', '¿No debía reír tan pronto?', '¿No debía reír tan pronto?', 'Рано смеяться?'),
	(1742, 'emote_laughing_at', 'Wait... what are we laughing at again?', 0, 0, '잠깐… 뭐 웃고 있었지?', 'Attends… on rigole sur quoi déjà ?', 'Moment… worüber lachen wir noch mal?', '等等……我们在笑啥来着？', '等等……我們在笑啥來著？', 'Espera… ¿de qué nos reímos?', 'Espera… ¿de qué nos reímos?', 'Погоди… над чем смеёмся?'),
	(1743, 'emote_medic', 'MEDIC! Stat!', 0, 0, '의무병! 빨리!', 'MÉDECIN ! Vite !', 'SANITÄTER! Sofort!', '医护！快！', '醫護！快！', '¡MÉDICO! ¡Rápido!', '¡MÉDICO! ¡Rápido!', 'МЕДИК! Срочно!'),
	(1744, 'emote_not_panic', 'Now is NOT the time to panic!', 0, 0, '지금 당황할 때가 아니야!', 'Ce n''est PAS le moment de paniquer !', 'JETZT ist nicht Zeit zum Panikmachen!', '现在可不是慌的时候！', '現在可不是慌的時候！', '¡NO es momento de entrar en pánico!', '¡NO es momento de entrar en pánico!', 'Сейчас НЕ время паниковать!'),
	(1745, 'emote_ouch', 'OUCH! Dammit, that hurt!', 0, 0, '아야! 아프잖아!', 'Aïe ! Merde, ça fait mal !', 'Autsch! Verdammt, das tut weh!', '哎哟！疼死了！', '哎喲！疼死了！', '¡Ay! Duele, maldita sea!', '¡Ay! Duele, maldita sea!', 'Ай! Больно же!'),
	(1746, 'emote_quite_welcome', 'You are quite welcome!', 0, 0, '천만에!', 'Je t''en prie !', 'Gern geschehen!', '不客气！', '不客氣！', '¡De nada!', '¡De nada!', 'Пожалуйста!'),
	(1747, 'emote_rawr', 'RAWR!', 0, 0, '으르렁!', 'ROAR !', 'RAWR!', '嗷！', '嗷！', '¡RAWR!', '¡RAWR!', 'РРР!'),
	(1748, 'emote_ready_here', 'Ready here, too!', 0, 0, '나도 준비됐어!', 'Prêt ici aussi !', 'Hier auch bereit!', '我这边也好了！', '我這邊也好了！', '¡Listo aquí también!', '¡Listo aquí también!', 'Я тоже готов!'),
	(1749, 'emote_right_back', 'Right back at you, bub!', 0, 0, '너한테도 돌려줄게!', 'Pareil pour toi, mon pote !', 'Gilt auch für dich!', '原样奉还，伙计！', '原樣奉還，夥計！', '¡Igual para ti!', '¡Igual para ti!', 'Тебе тоже!'),
	(1750, 'emote_shake_what', 'Shake what your mama gave you!', 0, 0, '엄마가 준 걸 흔들어봐!', 'Secoue ce que ta mère t''a donné !', 'Schüttel, was deine Mama dir gab!', '扭起来！', '扭起來！', '¡Sacude lo que te dio tu madre!', '¡Sacude lo que te dio tu madre!', 'Тряси, что мама дала!'),
	(1751, 'emote_shoo_yourself', 'Shoo yourself!', 0, 0, '네가 알아서 가!', 'Dégage !', 'Verschwinde!', '你自己走！', '你自己走！', '¡Lárgate!', '¡Lárgate!', 'Проваливай!'),
	(1752, 'emote_someone_agrees', 'At least SOMEONE agrees with me!', 0, 0, '적어도 누군가는 동의해!', 'Au moins QUELQU''UN est d''accord !', 'Wenigstens JEMAND stimmt mir zu!', '至少有人同意我！', '至少有人同意我！', '¡Al menos ALGUIEN está de acuerdo!', '¡Al menos ALGUIEN está de acuerdo!', 'Хоть КТО-ТО со мной согласен!'),
	(1753, 'emote_something_eye', 'What? You got something in your eye?', 0, 0, '뭐? 눈에 뭐 들어갔어?', 'Quoi ? T''as un truc dans l''œil ?', 'Was? Hast du was im Auge?', '啥？你眼里进东西了？', '啥？你眼裡進東西了？', '¿Qué? ¿Tienes algo en el ojo?', '¿Qué? ¿Tienes algo en el ojo?', 'Что? В глаз попало?'),
	(1754, 'emote_start_crying', 'Don''t you start crying or it''ll make me start crying!', 0, 0, '너 울기 시작하면 나도 울어!', 'Ne pleure pas ou je vais pleurer aussi !', 'Fang nicht an zu weinen, sonst heule ich mit!', '你别哭，不然我也要哭了！', '你別哭，不然我也要哭了！', '¡No llores o yo también!', '¡No llores o yo también!', 'Не плачь — я тоже заплачу!'),
	(1755, 'emote_stay_here', 'Fine.. I''ll stay right here..', 0, 0, '그래… 여기 있을게…', 'D''accord… je reste là…', 'Na gut… ich bleibe hier…', '行……我就待在这儿……', '行……我就待在這兒……', 'Vale… me quedo aquí…', 'Vale… me quedo aquí…', 'Ладно… останусь тут…'),
	(1756, 'emote_stop_that', 'Hey! Stop that!', 0, 0, '야! 그만해!', 'Hé ! Arrête !', 'Hey! Hör auf!', '嘿！别弄了！', '嘿！別弄了！', '¡Oye! ¡Para!', '¡Oye! ¡Para!', 'Эй! Хватит!'),
	(1757, 'emote_thanks_dots', 'Thanks...', 0, 0, '고마워…', 'Merci…', 'Danke…', '谢了……', '謝了……', 'Gracias…', 'Gracias…', 'Спасибо…'),
	(1758, 'emote_thanks_need_it', 'Thanks... I''ll need it..', 0, 0, '고마워… 필요할 거야…', 'Merci… j''en aurai besoin…', 'Danke… werde es brauchen…', '谢了……我会需要的……', '謝了……我會需要的……', 'Gracias… lo necesitaré…', 'Gracias… lo necesitaré…', 'Спасибо… пригодится…'),
	(1759, 'emote_want_some', 'What? You want some of this?', 0, 0, '뭐? 한번 덤벼?', 'Quoi ? Tu veux ta dose ?', 'Was? Willst du was ab?', '啥？你想来点？', '啥？你想來點？', '¿Qué? ¿Quieres un poco?', '¿Qué? ¿Quieres un poco?', 'Что? Хочешь попробовать?'),
	(1760, 'emote_wasnt_me', 'Wasn''t me! Just sayin''..', 0, 0, '내가 아니야! 그냥 말하는 거야…', 'C''était pas moi ! Je dis juste…', 'War ich nicht! Nur so…', '不是我！随便说说……', '不是我！隨便說說……', '¡No fui yo! Solo digo…', '¡No fui yo! Solo digo…', 'Не я! Просто говорю…'),
	(1761, 'emote_where_going', 'Umm.... wait! Where are you going?!', 0, 0, '어…… 잠깐! 어디 가?!', 'Euh… attends ! Tu vas où ?!', 'Äh… moment! Wohin?!', '呃……等等！你去哪儿？！', '呃……等等！你去哪兒？！', 'Eh… ¡espera! ¿Adónde vas?!', 'Eh… ¡espera! ¿Adónde vas?!', 'Эм… погоди! Куда?!'),
	(1762, 'emote_whole_class', 'I hope you brought enough for the whole class...', 0, 0, '반 전체 분량은 가져왔길…', 'J''espère que t''as apporté pour toute la classe…', 'Hoffentlich reicht''s für die ganze Klasse…', '希望你带够了全班份……', '希望你帶夠了全班份……', 'Ojalá trajiste para toda la clase…', 'Ojalá trajiste para toda la clase…', 'Надеюсь, принёс на весь класс…'),
	(1763, 'emote_why_not', 'Aww.... why not?!', 0, 0, '아…… 왜 안 돼?!', 'Aww… pourquoi pas ?!', 'Aww… warum nicht?!', '唉……为啥不行？！', '唉……為啥不行？！', 'Aww… ¿por qué no?!', 'Aww… ¿por qué no?!', 'Эх… почему нет?!'),
	(1764, 'emote_yay', 'Yay!', 0, 0, '야!', 'Youpi !', 'Juhu!', '耶！', '耶！', '¡Yay!', '¡Yay!', 'Ура!'),
	(1765, 'emote_you_dots', 'You.....', 0, 0, '너……', 'Toi……', 'Du……', '你……', '你……', 'Tú……', 'Tú……', 'Ты……'),
	(1766, 'emote_youre_sorry', 'You damn right you''re sorry!', 0, 0, '미안하다는 말이 맞아!', 'Tu as bien raison d''être désolé !', 'Du hast verdammt recht, sorry zu sein!', '你当然该道歉！', '你當然該道歉！', '¡Más te vale disculparte!', '¡Más te vale disculparte!', 'Тебе и правда стоит извиниться!'),
	(1767, 'error_autogear_no_alt', 'You cannot use autogear on alt bots.', 0, 0, '대체 봇에는 autogear를 쓸 수 없어요.', 'Impossible d''utiliser autogear sur les bots alts.', 'Autogear geht nicht bei Alt-Bots.', '你不能对替补机器人使用自动换装。', '你不能對替補機器人使用自動換裝。', 'No puedes usar autogear en bots alternos.', 'No puedes usar autogear en bots alternos.', 'Нельзя использовать autogear на альт-ботах.'),
	(1768, 'error_autogear_not_allowed', 'autogear command is not allowed, please check the configuration.', 0, 0, 'autogear 명령이 허용되지 않습니다. 설정을 확인하세요.', 'La commande autogear n''est pas autorisée, vérifiez la configuration.', 'Autogear-Befehl ist deaktiviert, prüfe die Konfiguration.', '不允许自动换装命令，请检查配置。', '不允許自動換裝命令，請檢查配置。', 'El comando autogear no está permitido, revisa la configuración.', 'El comando autogear no está permitido, revisa la configuración.', 'Команда autogear запрещена, проверьте конфигурацию.'),
	(1769, 'error_cannot_cast', 'Cannot cast %spell', 0, 0, '%spell 시전 불가.', 'Impossible de lancer %spell.', 'Kann %spell nicht wirken.', '无法施放 %spell', '無法施放 %spell', 'No puedo lanzar %spell.', 'No puedo lanzar %spell.', 'Не могу применить %spell.'),
	(1770, 'error_cannot_get_bags_full', 'Cannot get %item from %name - my bags are full', 0, 0, '%name에게서 %item 받을 수 없어요 — 가방이 가득 찼어요.', 'Impossible d''obtenir %item de %name — mes sacs sont pleins.', 'Kann %item von %name nicht nehmen — Taschen voll.', '无法从 %name 获得 %item，背包已满', '無法從 %name 獲得 %item，背包已滿', 'No puedo obtener %item de %name — mis bolsas están llenas.', 'No puedo obtener %item de %name — mis bolsas están llenas.', 'Не могу получить %item от %name — сумки полны.'),
	(1771, 'error_cannot_talk_quest_giver', 'Cannot talk to quest giver', 0, 0, '퀘스트 NPC와 대화할 수 없어요.', 'Impossible de parler au donneur de quête.', 'Kann nicht mit dem Questgeber sprechen.', '无法与任务NPC对话', '無法與任務NPC對話', 'No puedo hablar con el dador de misiones.', 'No puedo hablar con el dador de misiones.', 'Не могу поговорить с квестодателем.'),
	(1772, 'error_cannot_unlock_item', 'Cannot unlock this item.', 0, 0, '이 아이템을 열 수 없어요.', 'Impossible de déverrouiller cet objet.', 'Kann diesen Gegenstand nicht öffnen.', '无法解锁该物品。', '無法解鎖該物品。', 'No puedo abrir este objeto.', 'No puedo abrir este objeto.', 'Не могу вскрыть этот предмет.'),
	(1773, 'error_cant_go_there', 'I can''t go there', 0, 0, '거기는 못 가요.', 'Je ne peux pas aller là-bas.', 'Dahin kann ich nicht.', '我去不了那里', '我去不了那裡', 'No puedo ir allí.', 'No puedo ir allí.', 'Туда я не могу.'),
	(1774, 'error_cast_failed', 'Cast %spell is failed', 0, 0, '%spell 시전 실패.', 'Échec du lancement de %spell.', '%spell wirken fehlgeschlagen.', '施放 %spell 失败', '施放 %spell 失敗', 'Falló el lanzamiento de %spell.', 'Falló el lanzamiento de %spell.', 'Не удалось применить %spell.'),
	(1775, 'error_disperse_invalid', 'Invalid disperse distance %value', 0, 0, '잘못된 산개 거리 %value', 'Distance de dispersion invalide : %value', 'Ungültige Streu-Distanz %value', '无效的分散距离 %value', '無效的分散距離 %value', 'Distancia de dispersión inválida: %value', 'Distancia de dispersión inválida: %value', 'Неверная дистанция рассеивания %value'),
	(1776, 'error_failed_cast_pick_lock', 'Failed to cast Pick Lock.', 0, 0, 'Pick Lock 시전 실패.', 'Échec du lancement de Pick Lock.', 'Pick Lock fehlgeschlagen.', '施放开锁失败。', '施放開鎖失敗。', 'Falló Pick Lock.', 'Falló Pick Lock.', 'Не удалось применить Pick Lock.'),
	(1777, 'error_flag_usage', 'Usage: flag cloak/helm/pvp on/set/off/clear/toggle/?', 0, 0, '사용법: flag cloak/helm/pvp on/set/off/clear/toggle/?', 'Usage : flag cloak/helm/pvp on/set/off/clear/toggle/?', 'Nutzung: flag cloak/helm/pvp on/set/off/clear/toggle/?', '用法：flag cloak/helm/pvp on/set/off/clear/toggle/?', '用法：flag cloak/helm/pvp on/set/off/clear/toggle/?', 'Uso: flag cloak/helm/pvp on/set/off/clear/toggle/?', 'Uso: flag cloak/helm/pvp on/set/off/clear/toggle/?', 'Использование: flag cloak/helm/pvp on/set/off/clear/toggle/?'),
	(1778, 'error_formation_invalid', 'Invalid formation: %formation', 0, 0, '잘못된 대형: %formation', 'Formation invalide : %formation', 'Ungültige Formation: %formation', '无效阵型：%formation', '無效陣型：%formation', 'Formación inválida: %formation', 'Formación inválida: %formation', 'Неверное построение: %formation'),
	(1779, 'error_glyph_no_sockets', 'Not enought empty sockets for all glyphs.', 0, 0, '모든 문양을 장착할 빈 홈이 부족해요.', 'Pas assez d''emplacements vides pour tous les glyphes.', 'Nicht genug leere Sockel für alle Glyphen.', '没有足够的空插槽来装备所有雕文。', '沒有足夠的空插槽來裝備所有雕文。', 'No hay suficientes ranuras vacías para todos los glifos.', 'No hay suficientes ranuras vacías para todos los glifos.', 'Недостаточно пустых слотов для всех символов.'),
	(1780, 'error_gossip_need_talk', 'I need to talk first', 0, 0, '먼저 대화해야 해요.', 'Il faut que je parle d''abord.', 'Ich muss erst reden.', '我需要先对话', '我需要先對話', 'Primero tengo que hablar.', 'Primero tengo que hablar.', 'Сначала нужно поговорить.'),
	(1781, 'error_gossip_unknown', 'Unknown gossip option', 0, 0, '알 수 없는 대화 옵션', 'Option de dialogue inconnue', 'Unbekannte Gossip-Option', '未知的对话选项', '未知的對話選項', 'Opción de gossip desconocida.', 'Opción de gossip desconocida.', 'Неизвестный вариант диалога.'),
	(1782, 'error_guild_cant_put', 'I can''t put %item to guild bank. I have no rights to put items in the first guild bank tab', 0, 0, '%item을 길드 은행에 넣을 수 없어요. 첫 번째 길드 은행 탭에 넣을 권한이 없어요.', 'Je ne peux pas déposer %item à la banque de guilde — pas de droits sur le premier onglet.', 'Kann %item nicht in die Gildenbank legen — keine Rechte auf den ersten Tab.', '无法将 %item 放入公会银行，我没有第一页的存入权限', '無法將 %item 放入公會銀行，我沒有第一頁的存入權限', 'No puedo poner %item en el banco de hermandad — sin permisos en la primera pestaña.', 'No puedo poner %item en el banco de hermandad — sin permisos en la primera pestaña.', 'Не могу положить %item в банк гильдии — нет прав на первую вкладку.'),
	(1783, 'error_guild_happy', 'Sorry, I am happy in my guild :)', 0, 0, '미안, 지금 길드가 마음에 들어 :)', 'Désolé, je suis bien dans ma guilde :)', 'Sorry, ich bin glücklich in meiner Gilde :)', '抱歉，我在公会里很开心 :)', '抱歉，我在公會裡很開心 :)', 'Perdón, estoy contento en mi hermandad :)', 'Perdón, estoy contento en mi hermandad :)', 'Извини, мне нравится моя гильдия :)'),
	(1784, 'error_hire_cannot', 'You cannot hire me - I barely know you. Make sure you have at least %money as a trade discount', 0, 0, '날 고용할 수 없어요 — 아직 잘 모르잖아요. 거래 할인으로 최소 %money는 있어야 해요.', 'Tu ne peux pas m''embaucher — on se connaît à peine. Il faut au moins %money de remise commerciale.', 'Du kannst mich nicht anheuern — wir kennen uns kaum. Mindestens %money Handelsrabatt nötig.', '你还不能雇佣我，我们不够熟。请确保至少有 %money 作为交易折扣', '你還不能僱傭我，我們不夠熟。請確保至少有 %money 作為交易折扣', 'No puedes contratarme — apenas nos conocemos. Necesitas al menos %money de descuento comercial.', 'No puedes contratarme — apenas nos conocemos. Necesitas al menos %money de descuento comercial.', 'Ты не можешь меня нанять — мы едва знакомы. Нужно минимум %money торговой скидки.'),
	(1785, 'error_hire_level', 'You cannot hire higher level characters than you', 0, 0, '자기보다 레벨 높은 캐릭터는 고용할 수 없어요.', 'Tu ne peux pas embaucher un personnage de niveau supérieur.', 'Du kannst keine höherleveligen Charaktere anheuern.', '不能雇佣等级高于你的角色', '不能僱傭等級高於你的角色', 'No puedes contratar personajes de nivel superior al tuyo.', 'No puedes contratar personajes de nivel superior al tuyo.', 'Нельзя нанимать персонажей выше твоего уровня.'),
	(1786, 'error_hire_max_chars', 'You already have the maximum number of characters', 0, 0, '캐릭터 수가 이미 최대예요.', 'Tu as déjà le nombre maximum de personnages.', 'Du hast schon die maximale Charakteranzahl.', '你的角色数量已达上限', '你的角色數量已達上限', 'Ya tienes el número máximo de personajes.', 'Ya tienes el número máximo de personajes.', 'У тебя уже максимум персонажей.'),
	(1787, 'error_in_water', 'It is in water', 0, 0, '물 속에 있어요.', 'C''est dans l''eau.', 'Es ist im Wasser.', '目标在水中', '目標在水中', 'Está en el agua.', 'Está en el agua.', 'Это в воде.'),
	(1788, 'error_invalid_quest_whisper', 'Invalid quest %text', 0, 0, '잘못된 퀘스트 %text', 'Quête invalide %text', 'Ungültige Quest %text', '无效任务 %text', '無效任務 %text', 'Misión inválida %text', 'Misión inválida %text', 'Неверное задание %text'),
	(1789, 'error_lockpick_skill_too_low', 'Lockpicking skill too low (%current/%required) to unlock: %item', 0, 0, '자물쇠 해제 숙련도 부족 (%current/%required): %item', 'Crochetage trop faible (%current/%required) pour : %item', 'Schlossknacken zu niedrig (%current/%required) für: %item', '开锁技能不足（%current/%required）无法解锁：%item', '開鎖技能不足（%current/%required）無法解鎖：%item', 'Ganzúa muy baja (%current/%required) para: %item', 'Ganzúa muy baja (%current/%required) para: %item', 'Взлом слишком низкий (%current/%required) для: %item'),
	(1790, 'error_loot_guild_only', 'I will play with this loot type only if I''m in your guild :/', 0, 0, '길드에 있을 때만 이 루팅 방식 쓸게 :/', 'Je n''utilise ce type de loot que si je suis dans ta guilde :/', 'Diesen Loot-Modus nutze ich nur in deiner Gilde :/', '只有在你公会里我才会用这种拾取方式 :/', '只有在你公會裡我才會用這種拾取方式 :/', 'Solo uso este tipo de loot si estoy en tu hermandad :/', 'Solo uso este tipo de loot si estoy en tu hermandad :/', 'Такой лут-режим только в твоей гильдии :/'),
