	(2202, 'security_busy', 'I''m kind of busy now', 0, 0, '지금 좀 바빠.', 'Je suis un peu occupé.', 'Bin gerade beschäftigt.', '我现在有点忙', '我現在有點忙', 'Estoy algo ocupado.', 'Estoy algo ocupado.', 'Я сейчас занят.'),
