	(2209, 'security_in_bg_queue', 'I am in a queue for BG. Will do it later', 0, 0, '전장 대기 중이야. 나중에.', 'En file pour un BG — plus tard.', 'In BG-Warteschlange — später.', '我在战场队列中，稍后再做', '我在戰場佇列中，稍後再做', 'En cola de BG — luego.', 'En cola de BG — luego.', 'В очереди на BG — позже.'),
	(2210, 'security_in_group_other', 'I am in a group with someone else. You can ask him for invite.', 0, 0, '다른 사람이랑 파티 중이야. 그 사람한테 초대해 달라고 해.', 'Je suis en groupe avec quelqu''un d''autre — demande-lui une invite.', 'Bin mit jemand anderem in einer Gruppe — frag ihn.', '我和别人在一队，你可以找他邀请。', '我和別人在一隊，你可以找他邀請。', 'Estoy en grupo con otro — pídele invitación.', 'Estoy en grupo con otro — pídele invitación.', 'Я в группе с другим — попроси его пригласить.'),
	(2211, 'security_in_group_with', 'I am in a group with %name. You can ask him for invite.', 0, 0, '%name이랑 파티 중이야. 그 사람한테 초대해 달라고 해.', 'Je suis en groupe avec %name — demande-lui une invite.', 'Bin mit %name in einer Gruppe — frag ihn.', '我和 %name 在一队，你可以找他邀请。', '我和 %name 在一隊，你可以找他邀請。', 'Estoy en grupo con %name — pídele invitación.', 'Estoy en grupo con %name — pídele invitación.', 'Я в группе с %name — попроси его пригласить.'),
	(2212, 'security_in_lfg_queue', 'I am in a queue for dungeon. Will do it later', 0, 0, '던전 대기 중이야. 나중에.', 'En file pour un donjon — plus tard.', 'In Dungeon-Warteschlange — später.', '我在副本队列中，稍后再做', '我在副本佇列中，稍後再做', 'En cola de mazmorra — luego.', 'En cola de mazmorra — luego.', 'В очереди в подземелье — позже.'),
	(2213, 'security_invite_first', 'Invite me to your group first', 0, 0, '먼저 파티에 초대해.', 'Invite-moi d''abord dans ton groupe.', 'Lade mich erst in deine Gruppe ein.', '请先邀请我入队', '請先邀請我入隊', 'Invítame a tu grupo primero.', 'Invítame a tu grupo primero.', 'Сначала пригласи в группу.'),
	(2214, 'security_low_level', 'You are too low level: |cffff0000%from|cffffffff/|cff00ff00%bot', 0, 0, '레벨이 너무 낮아: |cffff0000%from|cffffffff/|cff00ff00%bot', 'Ton niveau est trop bas : |cffff0000%from|cffffffff/|cff00ff00%bot', 'Dein Level ist zu niedrig: |cffff0000%from|cffffffff/|cff00ff00%bot', '你等级太低：|cffff0000%from|cffffffff/|cff00ff00%bot', '你等級太低：|cffff0000%from|cffffffff/|cff00ff00%bot', 'Tu nivel es muy bajo: |cffff0000%from|cffffffff/|cff00ff00%bot', 'Tu nivel es muy bajo: |cffff0000%from|cffffffff/|cff00ff00%bot', 'Твой уровень слишком низкий: |cffff0000%from|cffffffff/|cff00ff00%bot'),
	(2215, 'security_too_far', 'You must be closer to invite me to your group. I am in %area', 0, 0, '파티 초대하려면 더 가까이 와. 나 %area에 있어.', 'Approche-toi pour m''inviter — je suis à %area.', 'Komm näher zum Einladen — ich bin in %area.', '请靠近些再邀请我入队。我在 %area', '請靠近些再邀請我入隊。我在 %area', 'Acércate para invitarme — estoy en %area.', 'Acércate para invitarme — estoy en %area.', 'Подойди ближе для приглашения — я в %area.'),
