	(2392, 'mail_body_greeting', 'Hello, %name,\n\n', 0, 0, '안녕하세요, %name님,\n\n', 'Bonjour %name,\n\n', 'Hallo %name,\n\n', '你好，%name：\n\n', '你好，%name：\n\n', 'Hola %name,\n\n', 'Hola %name,\n\n', 'Здравствуй, %name,\n\n'),
	(2393, 'mail_body_items_asked', 'Here are the item(s) you asked for', 0, 0, '요청하신 아이템입니다', 'Voici le(s) objet(s) que vous avez demandé(s)', 'Hier sind die angeforderten Gegenstände', '这是您要求的物品', '這是您要求的物品', 'Aquí tienes el/los objeto(s) que pediste', 'Aquí tienes el/los objeto(s) que pediste', 'Вот предмет(ы), которые вы просили'),
	(2394, 'mail_body_money_asked', 'Here is the money you asked for', 0, 0, '요청하신 금액입니다', 'Voici l''argent que vous avez demandé', 'Hier ist das angeforderte Geld', '这是您要的金币', '這是您要的金幣', 'Aquí tienes el dinero que pediste', 'Aquí tienes el dinero que pediste', 'Вот золото, которое вы просили'),
	(2395, 'mail_body_items_mistake', 'Here are the item(s) you''ve sent me by mistake', 0, 0, '실수로 보내주신 아이템입니다', 'Voici le(s) objet(s) que vous m''avez envoyé(s) par erreur', 'Hier sind die irrtümlich gesendeten Gegenstände', '这是您误发给我的物品', '這是您誤發給我的物品', 'Aquí tienes el/los objeto(s) que me enviaste por error', 'Aquí tienes el/los objeto(s) que me enviaste por error', 'Вот предмет(ы), которые вы прислали по ошибке'),
	(2396, 'mail_body_signoff', 'Thanks,\n%botname\n', 0, 0, '감사합니다,\n%botname\n', 'Merci,\n%botname\n', 'Danke,\n%botname\n', '谢谢,\n%botname\n', '謝謝,\n%botname\n', 'Gracias,\n%botname\n', 'Gracias,\n%botname\n', 'Спасибо,\n%botname\n'),
	(2397, 'msg_taxi_route', '%index: %dest', 0, 0, '%index: %dest', '%index: %dest', '%index: %dest', '%index: %dest', '%index: %dest', '%index: %dest', '%index: %dest', '%index: %dest'),
	(2398, 'msg_bot_add_not_allowed', 'Failure: You are not allowed to control bot %name', 0, 0, '실패: 봇 %name을(를) 제어할 권한이 없습니다', 'Échec : vous n''êtes pas autorisé à contrôler le bot %name', 'Fehler: Sie dürfen Bot %name nicht steuern', '失败：您无权控制机器人 %name', '失敗：您無權控制機器人 %name', 'Error: no tienes permiso para controlar al bot %name', 'Error: no tienes permiso para controlar al bot %name', 'Ошибка: у вас нет прав управлять ботом %name'),
	(2399, 'msg_bot_add_too_many', 'Failure: You have added too many bots (more than %max)', 0, 0, '실패: 추가한 봇이 너무 많습니다 (최대 %max)', 'Échec : vous avez ajouté trop de bots (plus de %max)', 'Fehler: Sie haben zu viele Bots hinzugefügt (mehr als %max)', '失败：您添加的机器人过多（超过 %max）', '失敗：您添加的機器人過多（超過 %max）', 'Error: has añadido demasiados bots (más de %max)', 'Error: has añadido demasiados bots (más de %max)', 'Ошибка: добавлено слишком много ботов (больше %max)'),
	(2400, 'msg_bot_disabled_chat', '|cffff0000Playerbot system is currently disabled!', 0, 0, '|cffff0000봇 시스템이 현재 비활성화되어 있습니다!', '|cffff0000Le système de bots est actuellement désactivé !', '|cffff0000Das Bot-System ist derzeit deaktiviert!', '|cffff0000机器人系统当前已禁用！', '|cffff0000機器人系統目前已禁用！', '|cffff0000¡El sistema de bots está desactivado!', '|cffff0000¡El sistema de bots está desactivado!', '|cffff0000Система ботов сейчас отключена!'),
	(2401, 'msg_bot_active_session_required', 'You may only add bots from an active session', 0, 0, '활성 세션에서만 봇을 추가할 수 있습니다', 'Vous ne pouvez ajouter des bots que depuis une session active', 'Bots können nur aus einer aktiven Sitzung hinzugefügt werden', '只能在已登录的角色会话中添加机器人', '只能在已登入的角色會話中添加機器人', 'Solo puedes añadir bots desde una sesión activa', 'Solo puedes añadir bots desde una sesión activa', 'Добавлять ботов можно только из активной сессии'),
	(2402, 'msg_bot_cannot_control_yet', 'You cannot control bots yet', 0, 0, '아직 봇을 제어할 수 없습니다', 'Vous ne pouvez pas encore contrôler les bots', 'Sie können Bots noch nicht steuern', '您还无法控制机器人', '您還無法控制機器人', 'Aún no puedes controlar bots', 'Aún no puedes controlar bots', 'Вы пока не можете управлять ботами'),
	(2403, 'msg_account_security_key_set', 'Security key set successfully.', 0, 0, '보안 키가 설정되었습니다.', 'Clé de sécurité définie avec succès.', 'Sicherheitsschlüssel erfolgreich gesetzt.', '安全密钥设置成功。', '安全金鑰設定成功。', 'Clave de seguridad establecida correctamente.', 'Clave de seguridad establecida correctamente.', 'Ключ безопасности успешно установлен.'),
	(2404, 'msg_account_not_found', 'Account not found.', 0, 0, '계정을 찾을 수 없습니다.', 'Compte introuvable.', 'Konto nicht gefunden.', '未找到账号。', '未找到帳號。', 'Cuenta no encontrada.', 'Cuenta no encontrada.', 'Аккаунт не найден.'),
	(2405, 'msg_account_invalid_security_key', 'Invalid security key.', 0, 0, '잘못된 보안 키입니다.', 'Clé de sécurité invalide.', 'Ungültiger Sicherheitsschlüssel.', '无效的安全密钥。', '無效的安全金鑰。', 'Clave de seguridad no válida.', 'Clave de seguridad no válida.', 'Неверный ключ безопасности.'),
	(2406, 'msg_account_linked_success', 'Account linked successfully.', 0, 0, '계정이 연결되었습니다.', 'Compte lié avec succès.', 'Konto erfolgreich verknüpft.', '账号关联成功。', '帳號關聯成功。', 'Cuenta vinculada correctamente.', 'Cuenta vinculada correctamente.', 'Аккаунт успешно связан.'),
	(2407, 'msg_account_no_linked', 'No linked accounts.', 0, 0, '연결된 계정이 없습니다.', 'Aucun compte lié.', 'Keine verknüpften Konten.', '没有关联账号。', '沒有關聯帳號。', 'No hay cuentas vinculadas.', 'No hay cuentas vinculadas.', 'Нет связанных аккаунтов.'),
	(2408, 'msg_account_linked_title', 'Linked accounts:', 0, 0, '연결된 계정:', 'Comptes liés :', 'Verknüpfte Konten:', '关联账号：', '關聯帳號：', 'Cuentas vinculadas:', 'Cuentas vinculadas:', 'Связанные аккаунты:'),
